@fail_wire(module="aria", gap_type="engine_failure")
def require_aria_token(request: Request) -> None:
    """FastAPI dependency that enforces a bearer-token check when
    either ARIA_API_TOKEN or ARIA_INTERNAL_TOKEN is set. No-op when both
    unset (soft rollout)."""
    global _AUTH_WARNING_LOGGED
    # R-F254: public-path bypass. Use the FULL request path so the check
    # is unambiguous (router prefix + endpoint path).
    if request.url.path in _PUBLIC_AUTH_BYPASS_PATHS:
        return
    accepted = _accepted_tokens()
    if not accepted:
        # R-F1566: fail CLOSED in production. The soft-rollout no-op (serve
        # open when no token is set) is only safe for local dev. On fly both
        # secrets ARE set, so an empty `accepted` in production means the
        # secrets were cleared/lost — serving open then would silently expose
        # every endpoint. Detect production via FLY_APP_NAME (set on every fly
        # machine; absent locally) and refuse rather than serve unauthenticated.
        import os as _os
        if _os.getenv("FLY_APP_NAME") or _os.getenv("FLY_MACHINE_ID"):
            _log.error(
                "[auth] PRODUCTION with NO ARIA_API_TOKEN/ARIA_INTERNAL_TOKEN set "
                "— refusing all requests (fail-closed, R-F1566). Set the secret."
            )
            raise HTTPException(
                status_code=503,
                detail="Service auth not configured — refusing (fail-closed).",
            )
        if not _AUTH_WARNING_LOGGED:
            _log.warning(
                "[auth] Neither ARIA_API_TOKEN nor ARIA_INTERNAL_TOKEN set — "
                "local dev soft-rollout (no enforcement). In production this "
                "fails closed (R-F1566)."
            )
            _AUTH_WARNING_LOGGED = True
        # R-F3628 — DECLARE the permissive posture instead of inheriting it. This is
        # the only path that legitimately wants it (local dev, no tokens, no
        # enforcement); production with missing tokens raises 503 above (R-F1566).
        _auth_is_internal_var.set(True)
        return
    auth_header = request.headers.get("Authorization", "")
    if not auth_header.lower().startswith("bearer "):
        raise HTTPException(
            status_code=401,
            detail="Missing or malformed Authorization header. Expected 'Bearer <token>'.",
        )
    presented = auth_header[7:].strip()
    # Constant-time comparison via hmac.compare_digest. We compare against
    # both tokens; if either matches, the request is authorized.
    import hmac as _hmac
    if not any(_hmac.compare_digest(presented, t) for t in accepted):
        raise HTTPException(status_code=401, detail="Invalid bearer token")

    # R-F2138 — record which token type authenticated, so downstream
    # per-user-route logic can distinguish internal (service-to-service,
    # unrestricted) from external (user-facing API token, must scope).
    # Internal token = service-to-service (WA listener, web proxy, CLI).
    # API token = user-facing (external callers, must have user_id).
    # R-F2456: bind to the request's task context (was a racy module global).
    # ── R-F3709 — derive "internal" by POSITIVE IDENTITY, not by negation ────
    #
    # THE DEFECT: this was `presented != ARIA_API_TOKEN`, i.e. "internal" meant
    # "some accepted token that is not the user-facing one". `_accepted_tokens()`
    # returns FOUR tokens (api, internal, operator, service), so THREE of them
    # set this flag — and the flag unlocks unscoped cross-tenant DD access at
    # `_dd_report_access_allowed`, `dd_reports_index_ep` and
    # `_dd_owned_entity_ids`, which between them cover nine endpoints INCLUDING
    # `DELETE /dd/report/{run_id}` and its sibling cascade.
    #
    # Two live consequences, both measured on 2026-08-04:
    #  1. ARIA_OPERATOR_TOKEN and ARIA_SERVICE_TOKEN silently inherited
    #     unrestricted cross-tenant DD read AND delete. Neither is meant to.
    #  2. The whole branch's safety depended on an ACCIDENT. CLAUDE.md §18
    #     recorded ARIA_API_TOKEN and ARIA_INTERNAL_TOKEN as byte-identical, so
    #     `presented != api_tok` was never true and the path was dead code. When
    #     the tokens were rotated apart the path went live — with no code change,
    #     no test failure, and no signal. A security boundary that flips on a
    #     SECRET-ROTATION ASYMMETRY is not a boundary.
    #
    # Deriving it positively removes both: only the internal service token sets
    # the flag, and the result no longer depends on ARIA_API_TOKEN's value at
    # all, so no future rotation can arm it again.
    _int_tok = _aria_internal_token()
    _auth_is_internal_var.set(
        bool(_int_tok and _hmac.compare_digest(presented, _int_tok))
    )
    # R-F3709 — operator tier, recorded positively and independently.
    _op_tok_id = _aria_operator_token()
    _auth_is_operator_var.set(
        bool(_op_tok_id and _hmac.compare_digest(presented, _op_tok_id))
    )

    # R-F2139 — Per-service token scoping: ON by default when ARIA_OPERATOR_TOKEN
    # is set. Control/destructive routes require the OPERATOR token — the shared
    # service token (held by the WA listener + web tier) can chat/read/telemetry
    # but cannot drive the control plane (autonomous, self-deploy, cost-cap, purge,
    # credentials, restore). Set ARIA_TOKEN_SCOPING=0 to disable (not recommended).
    import os as _os_p3  # local alias — require_aria_token rebinds _os later (UnboundLocal otherwise)
    _scoping_disabled = (_os_p3.getenv("ARIA_TOKEN_SCOPING") or "").strip() == "0"
    if not _scoping_disabled:
        _op = _aria_operator_token()
        if _op:
            _p3_path = request.url.path or ""
            # R-F2374: operator-only if the path matches the control/destructive
            # regex, OR it's a DELETE against a global-vault path (method-aware —
            # GET/POST vault reads/writes stay service-tier).
            _op_only = bool(_OPERATOR_ONLY_RE.search(_p3_path)) or (
                getattr(request, "method", "") == "DELETE"
                and bool(_OPERATOR_ONLY_DELETE_RE.search(_p3_path))
            )
            if _op_only and not _hmac.compare_digest(presented, _op):
                raise HTTPException(
                    status_code=403,
                    detail="Operator-tier token required for this control/destructive endpoint.",
                )


# ── Input sanitisation ──────────────────────────────────────────────────────
_COUNTRY_RE = re.compile(r"^[a-zA-Z\s\-']{2,60}$")

def _validate_country(country: str) -> str:
    """Sanitise country parameter — alphanumeric + spaces only."""
    c = country.strip()
    if not _COUNTRY_RE.match(c):
        raise HTTPException(status_code=400, detail="Invalid country parameter")
    return c


# ── Request/Response Models ──────────────────────────────────────────────────

class ChatRequest(BaseModel):
    message: str
    session_id: str = ""
    user_id: str = ""         # authenticated user ID (injected by Node proxy)
    user_email: str = ""      # R-F2202: JWT-pinned email (Node proxy) → chat-DD company sharing
    user_tier: str = ""       # R-F2767: subscription tier (Node proxy) → per-tier Claude cost attribution
    # R-F3590 — display name of the person speaking, supplied by the channel
    # (WhatsApp pushName, web profile name). SELF-DECLARED and trivially
    # spoofable, so the engine labels it unverified unless a bound account
    # (R-F3587) accompanies it. Carried so ARIA can use someone's name; never
    # used for authorisation.
    speaker_name: str = ""
    auto_tools: bool = True   # auto-detect intent and call investigate/crawl/read tools
    # R-F48a: persona overlay key. Tunes which constitution clauses are
    # weighted most heavily in the system prompt. Recognised values:
    # broker, oem_export, government_acquisition, compliance,
    # banking_insurance, journalist. Empty / unrecognised → broker
    # (current default behaviour). Resolved by the Node proxy from the
    # authenticated user's `sector` field at registration time.
    persona: str = ""
    # Group context as a SEPARATE field — populated by the WhatsApp listener
    # with the last 5 group messages so ARIA has multi-participant context.
    # The chat handler treats this as an ADDITIONAL context layer (not as
    # part of the user's message body) to avoid the prior-turn topic bleed
    # that caused the DUMA / Iraq incident on 2026-04-09. Empty string when
    # the caller is a single-user channel (curl, frontend, /ask command).
    group_context: str = ""
    # R-F1691 (2026-06-19) — edit-&-resend. When the web UI edits a previous
    # user message, it removes that message + everything after it from view and
    # sends `keep_history` = the number of prior session messages to retain. The
    # engine trims session["messages"] to that length BEFORE processing this
    # turn, so the backend thread matches what the user sees. None = no trim
    # (normal send). Out-of-range values are clamped/ignored defensively.
    keep_history: int | None = None
    # R-F916 (2026-05-26) — async job mode. When true, /chat enqueues a
    # background task that runs the FULL chat handler (sync path) and returns
    # a job_id immediately; the caller polls /chat/result/{job_id}. This is for
    # URL-bearing questions whose fresh crawl + multi-page synthesis routinely
    # ran past the WhatsApp listener's 90s brainPost timeout → the
    # "⚠️ ARIA is temporarily unavailable." incident (2026-05-26 16:53/16:56Z).
    # Mirrors the R-F873 read-document async job pattern exactly.
    async_mode: bool = False
    # R-F1413 (2026-06-07) — async-complete-and-push: optional callback URL.
    # When set, the brain POSTs the completed job result to this URL as a
    # fire-and-forget background task. This is the safety net for deep queries
    # that exceed the WA listener's poll budget — the result arrives via
    # callback even if the poll loop times out. The callback URL should point
    # to the caller's delivery endpoint (e.g. WA listener's /api/wa-listener/send).
    callback_url: str = ""
    # Internal: the async wrapper stamps its own job id here before re-entering
    # chat_ep synchronously, so the chat path can post OBSERVED progress back
    # into the job record while it works. Never set by an external caller —
    # there is nothing useful a client could do with it, and a wrong value only
    # writes progress to a job the writer already owns.
    #
    # Why observed and not predicted: R-F3664 removed interim messages that
    # claimed "checking multiple sources" on a pure timer, because the listener
    # cannot see what the brain is doing. Detecting the intent EARLY and telling
    # the user about it would rebuild the same lie one layer up — the ML
    # detector can still decline, and a prediction that does not happen is
    # exactly the fabrication being guarded against. This field lets the tier
    # that ACTUALLY runs the tool say so, after it has started.
    progress_job_id: str = ""


# R-F1953 — derive the PER-USER quota key. The old `session_id.split("_", 1)[0]`
# collapsed every channel into ONE shared bucket: WhatsApp sessions are
# `wa_<jid>` → "wa", Telegram `telegram_<chatid>` → "telegram", WA auto-response
# `auto_<jid>` → "auto". So 30 RPM + $5/day were SHARED across every WhatsApp
# team member (one chatty user starved the rest) — the opposite of per-user
# scoping. Fix: prefer the JWT-pinned user_id (the web proxy injects a stable
# per-account slug); for channels that don't inject one, the per-SENDER identity
# is embedded in the FULL session_id, so key on that instead of the channel
# prefix. Web is unchanged (it always sends user_id == the same slug the old
# split produced); WA/Telegram/auto/api sessions now get one bucket per sender.
def _quota_user_key(req: "ChatRequest") -> str:
    uid = (getattr(req, "user_id", "") or "").strip()
    if uid:
        return uid
    sid = (getattr(req, "session_id", "") or "").strip()
    return sid or "anon"


# R-F1976 — ADAPTIVE FAST-LANE router. Decides whether a question is CLEARLY
# basic enough to answer with a single lean LLM call (fast_lane_chat), skipping
# the heavy 7-layer context build + tool execution + verification. CONSERVATIVE
# by design — every off-ramp routes to the FULL grounded pipeline, so the
# no-fabrication / DD / compliance path is never weakened. When in any doubt → full.
_FAST_LANE_HEAVY_KW = (
    "investigate", "due diligence", " dd ", "diligence", "screen", "sanction",
    "compliance", "profile", "research", "crawl", "registry", "registration",
    "registr", "beneficial owner", "export", "licens", "embargo", "itar",
    "dual-use", "dual use", "pep ", "adverse media", "ofac", "ofsi", "number of",
    "background check", "look up", "look into", "find out about", "report on",
    "verify ", "vet ", "kyc", "ubo", "shareholder", "director of",
)
_FAST_LANE_ENTITY_RE = re.compile(r"\b[A-Z][a-z]{2,}\s+[A-Z][a-z]{2,}")  # 2+ Capitalized words → likely a named entity


def _fast_lane_eligible(message: str) -> bool:
    m = (message or "").strip()
    if not m or len(m) > 280:           # long asks usually need real context
        return False
    if "[ATTACHED DOCUMENT" in message:  # documents → full review path
        return False
    ml = m.lower()
    if "http://" in ml or "https://" in ml or "www." in ml:   # URLs → crawl/extract
        return False
    if any(k in ml for k in _FAST_LANE_HEAVY_KW):              # compliance/entity intent → full
        return False
    try:
        if _detect_tool_intent(m) is not None:                # any tool intent → full
            return False
    except Exception:
        return False                                          # unsure → full
    try:
        from ..intel import comprehension as _comp
        ca = _comp.analyse(m)
        if not getattr(ca, "is_trivial", False):
            _cv = (getattr(getattr(ca, "complexity", None), "value", "") or "").lower()
            if _cv not in ("simple", "low", "trivial", "basic", ""):
                return False                                  # non-trivial → full
    except Exception:
        pass
    if _FAST_LANE_ENTITY_RE.search(m):                         # named entity → full (grounding)
        return False
    return True


