@router.post("/dd/evidence-standard/validate")
@fail_wire(module="aria", gap_type="engine_failure")
async def dd_evidence_standard_validate_ep(req: Request):
    """R-F3069 — validate an evidence record without persisting it."""
    from ..intel.dd_evidence_standard import EvidenceContractError, EvidenceRecord

    candidate = await req.json()
    try:
        record = EvidenceRecord.from_mapping(candidate)
    except EvidenceContractError as exc:
        raise HTTPException(
            status_code=422,
            detail={"code": "invalid_evidence_record", "errors": list(exc.errors)},
        ) from exc
    return {"valid": True, "record": record.as_dict()}


@router.post("/dd/evidence")
@fail_wire(module="aria", gap_type="engine_failure")
async def dd_evidence_append_ep(req: Request):
    """R-F3083 — hash-verify and append one canonical evidence record."""
    import asyncio
    import base64
    import binascii
    import json

    from ..intel.dd_evidence_standard import EvidenceContractError
    from ..intel.dd_evidence_store import (
        EvidencePersistenceError,
        get_evidence_store,
    )

    request_bytes = await req.body()
    max_request_bytes = 24 * 1024 * 1024
    if len(request_bytes) > max_request_bytes:
        raise HTTPException(
            status_code=413,
            detail={"code": "evidence_request_too_large"},
        )
    try:
        body = json.loads(request_bytes)
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise HTTPException(
            status_code=422,
            detail={"code": "invalid_evidence_request",
                    "errors": ["request body must be valid JSON"]},
        ) from exc
    if not isinstance(body, dict) or not isinstance(body.get("record"), dict):
        raise HTTPException(
            status_code=422,
            detail={"code": "invalid_evidence_request",
                    "errors": ["record must be an object"]},
        )
    artifact_base64 = body.get("artifact_base64")
    artifact = None
    if artifact_base64 is not None:
        if not isinstance(artifact_base64, str):
            raise HTTPException(
                status_code=422,
                detail={"code": "invalid_evidence_request",
                        "errors": ["artifact_base64 must be a string"]},
            )
        try:
            artifact = base64.b64decode(artifact_base64, validate=True)
        except (binascii.Error, ValueError) as exc:
            raise HTTPException(
                status_code=422,
                detail={"code": "invalid_evidence_request",
                        "errors": ["artifact_base64 is not valid base64"]},
            ) from exc
        if len(artifact) > 16 * 1024 * 1024:
            raise HTTPException(
                status_code=413,
                detail={"code": "evidence_artifact_too_large"},
            )
    try:
        evidence_store = await asyncio.to_thread(get_evidence_store)
        result = await asyncio.to_thread(
            evidence_store.append, body["record"], artifact)
    except (EvidenceContractError, EvidencePersistenceError) as exc:
        errors = list(getattr(exc, "errors", (str(exc),)))
        raise HTTPException(
            status_code=422,
            detail={"code": "evidence_not_persisted", "errors": errors},
        ) from exc
    return result.as_dict()


@router.get("/dd/evidence/{evidence_id}")
@fail_wire(module="aria", gap_type="engine_failure")
async def dd_evidence_get_ep(evidence_id: str, tenant_id: str):
    """R-F3083 — retrieve evidence only through its explicit tenant boundary."""
    import asyncio

    from ..intel.dd_evidence_store import get_evidence_store

    evidence_store = await asyncio.to_thread(get_evidence_store)
    result = await asyncio.to_thread(
        evidence_store.get, tenant_id, evidence_id)
    if result is None:
        raise HTTPException(status_code=404, detail="Evidence record not found")
    integrity = result["integrity"]
    if (
        not integrity["metadata_valid"]
        or integrity["artifact_valid"] is False
    ):
        raise HTTPException(
            status_code=409,
            detail={"code": "evidence_integrity_failure"},
        )
    return result


def _brave_scope(fn):
    """R-F2318 — open a search scope for the wrapped user-facing handler.

    ⚠️ R-F3946 — THIS NO LONGER GRANTS BRAVE, and that is deliberate.

    RULE ONE (operator, 2026-08-12, CLAUDE.md §17) confines Brave to DD reports.
    This decorator sits on EIGHT routes — including `POST /chat`, `/explore`,
    `/explore-deep` and `/research/spawn` — so while it granted Brave, every
    general chat turn that searched was spending the paid DD key. Measured: 65
    Brave calls in a month against a handful of DD reports, while
    `rule_one_status()` reported `breached: false` because it only ever checked
    Anthropic.

    The scope now carries a PURPOSE and this one declares none, so
    `web_search.brave_is_enabled()` refuses it. DD is unaffected — it opens its
    own `purpose="dd"` scope in dd_orchestrator and never depended on this
    decorator (see the R-F3087 invariants).

    Kept rather than deleted from the eight routes because the R-F3087
    restoration contract is still live and still tested, and because curating a
    route list is the whack-a-mole this fix replaced: the policy is enforced at
    one predicate now, so a ninth route cannot silently re-open the breach.
    Best-effort.
    """
    import functools as _ft

    @_ft.wraps(fn)
    async def _wrapped(*args, **kwargs):
        _brave_token = None
        _brave_module = None
        try:
            from ..intel import web_search as _ws_brave
            _brave_module = _ws_brave
            _brave_token = _ws_brave.enable_brave_for_scope(True)
        except Exception:
            pass
        try:
            return await fn(*args, **kwargs)
        finally:
            # R-F3087 — ASGI implementations normally isolate request tasks, but
            # the paid-backend boundary must not depend on that implementation
            # detail. Restore the incoming context on success and failure.
            if _brave_token is not None and _brave_module is not None:
                try:
                    _brave_module.reset_brave_scope(_brave_token)
                except Exception:
                    pass

    return _wrapped


_DD_PLACEHOLDER_ENTITY_NAMES = frozenset({
    "",
    "(unknown)",
    "(unnamed)",
    "unknown",
    "unnamed",
    "n/a",
    "none",
    "null",
})


def _dd_placeholder_entity_name(value: Any) -> bool:
    """Return True for DD display placeholders that must not be screened."""
    return str(value or "").strip().lower() in _DD_PLACEHOLDER_ENTITY_NAMES


def _dd_first_real_entity_name(*values: Any) -> str:
    """Return the first non-placeholder DD entity name from candidate fields."""
    for value in values:
        text = str(value or "").strip()
        if text and not _dd_placeholder_entity_name(text):
            return text
    return ""


async def _hydrate_dd_rerun_lineage(body: dict) -> None:
    """Carry prior DD identity into an explicit re-run body.

    Re-runs must version the same case even when the browser only has a
    previous run id. The persisted report is the source of truth for identity
    fields that are easy to lose in display rows: canonical id, ISO2
    jurisdiction, registration number, and website.
    """
    previous_run_id = (body.get("previous_run_id") or body.get("rerun_of_run_id") or "").strip()
    if not previous_run_id:
        return
    try:
        from ..intel import redis_store as rs
        from ..intel import dd_orchestrator as _ddo
        previous = await rs.get_json(_ddo.REPORT_REDIS_KEY.format(run_id=previous_run_id))
    except Exception as exc:
        _log.debug("DD re-run lineage hydrate failed for %s: %s", previous_run_id, exc)
        return
    if not isinstance(previous, dict):
        return
    ident = previous.get("identity") if isinstance(previous.get("identity"), dict) else {}
    target = previous.get("target") if isinstance(previous.get("target"), dict) else {}

    def _fill(key: str, value: Any) -> None:
        if value not in (None, "") and _dd_placeholder_entity_name(body.get(key)):
            body[key] = value

    prior_name = (
        ident.get("entity_name")
        or previous.get("entity_name")
        or target.get("name")
        or target.get("entity")
        or target.get("query")
    )
    _fill("canonical_entity_id", previous.get("canonical_entity_id") or ident.get("canonical_entity_id"))
    _fill("name", prior_name)
    _fill("entity", prior_name)
    _fill("type", ident.get("entity_type"))
    _fill("entity_type", ident.get("entity_type"))
    _fill("jurisdiction", ident.get("jurisdiction"))
    _fill("jurisdiction_iso2", ident.get("jurisdiction_iso2"))
    _fill("registration_number", ident.get("registration_number"))
    _fill("website_url", target.get("website_url") or target.get("website") or target.get("url"))
    if body.get("website_url") and not body.get("website"):
        body["website"] = body["website_url"]
    body["_rerun_lineage"] = {
        "previous_run_id": previous_run_id,
        "canonical_entity_id": body.get("canonical_entity_id"),
        "entity_name": prior_name,
        "jurisdiction": ident.get("jurisdiction"),
        "jurisdiction_iso2": ident.get("jurisdiction_iso2"),
        "registration_number": ident.get("registration_number"),
    }


@router.post("/dd/orchestrate")
@fail_wire(module="aria", gap_type="engine_failure")
@_brave_scope
async def dd_orchestrate_ep(req: Request):
    """Run the 7-layer DD orchestrator on a target entity.

    Request body (JSON):
      {
        "name":                  str (required),
        "type":                  "company" | "person" | "address" | "vessel",
        "jurisdiction_iso2":     "GB" | "AO" | ...,
        "jurisdiction":          "United Kingdom" | "Angola" | ...,
        "registration_number":   "12345678",
        "website_url":           "https://company.com",
        "product_description":   "Bayraktar TB2 UAVs + munitions",
        "transaction_value_usd": 50000000,
        "mode":                  "quick" | "standard" | "deep",
        "format":                "json" | "markdown"    (default json)
      }
    """
    body = await req.json()
    if not isinstance(body, dict) or not (body.get("name") or body.get("entity")):
        raise HTTPException(status_code=400, detail="request body must include 'name' or 'entity'")

    # R-F2767 — attribute this DD's Claude spend to the caller's subscription tier
    # (forwarded by the Node proxy as body.user_tier). DD is the cost-heavy path, so
    # per-tier attribution matters most here; the contextvar propagates to the ~15-25
    # parallel LLM calls the orchestrator fires.
    try:
        _dd_tier = (body.get("user_tier") or "").strip()
        if _dd_tier:
            from ..intel import cost_tracker as _ct2767
            _ct2767.set_tier(_dd_tier)
    except Exception:
        pass

    # Map website_url -> website for the orchestrator before lineage repair so
    # route-level validation and downstream canonicalisation see one identity.
    if body.get("website_url") and not body.get("website"):
        body["website"] = body["website_url"]

    await _hydrate_dd_rerun_lineage(body)

    # R-F2352 — the RE-RUN paths (row + detail buttons) send `entity_type`, but the
    # orchestrator's R-F659 gate requires `target['type']`. Without this mapping every
    # re-run fast-failed in the background ("R-F659: entity_type missing") — the DD never
    # completed and (with R-F2341) showed 'Failed'. The New-DD modal already sends `type`,
    # so only re-run was broken. Normalise so BOTH field names work.
    if body.get("entity_type") and not body.get("type"):
        body["type"] = body["entity_type"]

    _resolved_entity_name = _dd_first_real_entity_name(body.get("name"), body.get("entity"))
    if _dd_placeholder_entity_name(_resolved_entity_name):
        raise HTTPException(
            status_code=422,
            detail=(
                "DD target identity is unresolved. Open the original case or run "
                "New DD with the entity name; placeholder names cannot be re-run."
            ),
        )
    if _dd_placeholder_entity_name(body.get("name")):
        body["name"] = _resolved_entity_name
    if _dd_placeholder_entity_name(body.get("entity")):
        body["entity"] = _resolved_entity_name

    # R-F1655: check the DD vault for existing cases on this entity
    # before running a new DD. If found, return the existing summary
    # with an option to re-run (unless force=true is set).
    try:
        from ..intel.dd_vault import get_vault as _get_dd_vault
        from ..intel.dd_versioning import canonical_entity_id as _canonical_id
        _entity_name = body.get("name") or body.get("entity") or ""
        # R-F1842 — canonical_entity_id is keyword-only (def …(*, entity_type,
        # name, …)); the old positional call _canonical_id(_entity_name) raised
        # TypeError on EVERY request, which the except below then escalated to a
        # 500 (see the logger fix). Pass the same identifying fields the persist
        # path uses so the vault key matches a previously-stored case.
        _canonical = _canonical_id(
            entity_type=body.get("type") or "company",
            name=_entity_name,
            jurisdiction_iso2=body.get("jurisdiction_iso2"),
            registration_number=body.get("registration_number"),
        )
        if _canonical and not body.get("force"):
            # ── R-F3700 — the vault pre-check must be TENANT-SCOPED ──────────
            #
            # THE DEFECT: `DDVault.get_case` (intel/dd_vault.py:475-484) is a
            # bare `SELECT * FROM dd_cases WHERE canonical_entity_id = ?` — the
            # vault is entity-keyed with NO owner column. This route called it
            # with no scoping at all, so tenant B submitting a DD for an entity
            # tenant A had already run received A's `risk_level`, `risk_score`,
            # `findings_summary`, `last_run_at` and `run_count`.
            #
            # `canonical_entity_id` is deterministic over name + jurisdiction +
            # registration number — all PUBLIC inputs — so the "attack" is just
            # submitting a competitor's details. And because the short-circuit
            # returns before any work happens, it consumed no quota: the leak
            # was also the CHEAP path.
            #
            # R-F2097 already gated the sibling read (`/dd/case/{id}`, ~:1620)
            # with exactly this oracle; this route was missed.
            #
            # Deliberately NOT 404-ing on a cross-tenant miss, unlike that
            # sibling: the caller is entitled to run their OWN DD on this
            # entity. We simply decline the short-circuit and fall through to
            # the real run, so an unowned entity is indistinguishable from a
            # never-before-seen one — which is the honest state from that
            # tenant's point of view.
            _vault_owner_id = (body.get("user_id") or "").strip()
            _vault_owner_domain = (body.get("user_email_domain") or "").strip()
            _vault_owned = await _dd_owned_entity_ids(_vault_owner_id, _vault_owner_domain)
            # `None` = unrestricted (internal/service caller); a set = scoped.
            # `_dd_owned_entity_ids` fails CLOSED to an empty set on error.
            _may_reuse = _vault_owned is None or _canonical in _vault_owned
        else:
            _may_reuse = False
        if _canonical and not body.get("force") and _may_reuse:
            _vault = _get_dd_vault()
            _existing = _vault.get_case(_canonical)
            if _existing:
                return {
                    "existing_case": True,
                    "canonical_entity_id": _canonical,
                    "entity_name": _existing.get("entity_name", _entity_name),
                    "last_run_at": _existing.get("last_run_at"),
                    "run_count": _existing.get("run_count", 1),
                    "risk_score": _existing.get("risk_score", 0.0),
                    "risk_level": _existing.get("risk_level", "unknown"),
                    "findings_summary": _existing.get("findings_summary", ""),
                    "message": (
                        f"DD already exists for {_existing.get('entity_name', _entity_name)} "
                        f"(last run {_existing.get('run_count', 1)} times). "
                        f"Set force=true to re-run."
                    ),
                }
    except Exception as _vault_check_err:
        # R-F1842 — was `logger.debug`, but the module logger is `_log`; the
        # NameError turned this "non-fatal" guard into a guaranteed 500.
        _log.debug("dd_vault check failed (non-fatal): %s", _vault_check_err)

    mode = (body.get("mode") or "standard").lower()
    if mode not in ("quick", "standard", "deep"):
        mode = "standard"
    output_format = (body.get("format") or "json").lower()

    llm = get_llm(req)

    # Start a trace so /api/aria/trace/{trace_id} shows the DD lifecycle.
    trace_id = await trace_stream.start_trace(
        question=f"dd_orchestrate: {body.get('name') or body.get('entity')}",
        session_id=body.get("session_id", ""),
        user=body.get("user", ""),
        # R-F1865 (audit DD-02): JWT-pinned owner so GET /trace/{id} can
        # enforce ownership. Node pins body.user_id from the JWT.
        user_id=(body.get("user_id") or "").strip(),
        source="dd_orchestrator",
    )

    # R-F607 (2026-05-16): forward the originating user's identity into
    # the orchestrator so the persisted report carries `user_id` (and the
    # R-F608 `user_email_domain` for company-shared visibility). The Node
    # proxy pins these to JWT-resolved values, so the body fields can be
    # trusted at this layer.
    _req_user_id = (body.get("user_id") or "").strip() or None
    _req_user_email = (body.get("user_email") or "").strip() or None

    # R-F608 (2026-05-16): per-DD opt-out toggle. Default True (every DD
    # run by a user is visible to colleagues on the same email domain).
    # The orchestrate form can set this to False on sensitive screens.
    _share_to_company = body.get("share_to_company")
    if _share_to_company is None:
        _share_to_company = True
    else:
        _share_to_company = bool(_share_to_company)

    # R-F2250 — ASYNC DD (fire-and-poll). A full DD runs minutes; a SYNCHRONOUS
    # request dies at the aria-web ariaProxy (~30s) / Fly edge (~60s) timeout →
    # "DD failed (HTTP 500)" even though the DD completes server-side. When
    # async_mode is set, launch the DD in the background under a pre-assigned run_id
    # and return it IMMEDIATELY; the caller polls GET /dd/report/{run_id}.
    if body.get("async_mode") or body.get("async"):
        import uuid as _uuid
        from ..intel import dd_orchestrator as _ddo
        # R-F3007 — validate the target UPFRONT (the SAME R-F659 entity_type guard the
        # sync path and the bg orchestrate enforce) so an under-specified request —
        # e.g. a missing entity_type — fails LOUDLY here with a 400, instead of
        # returning "running" and then silently refusing inside the detached bg task.
        # That silent path marked the run and then dropped it, leaving the caller
        # polling a run_id that never lands (no report, no visible error) — the exact
        # not-robust failure a DD platform must not have.
        _type_ok, _type_reason = _ddo._validate_entity_type_for_dd(body)
        if not _type_ok:
            raise HTTPException(status_code=400, detail=(
                f"R-F659: refusing DD on unclassified target: {_type_reason}. "
                f"Pass target['type'] as one of {sorted(_ddo._DD_VALID_ENTITY_TYPES)}."
            ))
        _run_id = f"dd_{_uuid.uuid4().hex[:12]}"
        _ent = body.get("name") or body.get("entity") or ""
        # R-F2341 — carry the owner identity so the 'running' index row is scoped to (and
        # visible to) the requesting user under the R-F607/608 list filter.
        _email_lower = (_req_user_email or "").strip().lower() or None
        _email_domain = (body.get("user_email_domain") or "").strip().lower() or (
            _email_lower.split("@")[-1] if _email_lower and "@" in _email_lower else None)
        await _ddo.mark_dd_running(
            _run_id, _ent, mode, body.get("canonical_entity_id") or locals().get("_canonical"),
            user_id=_req_user_id, user_email_lower=_email_lower,
            user_email_domain=_email_domain, share_to_company=_share_to_company,
            target=body,  # R-F3009 — stored so a restart-killed run can be resumed
        )

        async def _bg_dd():
            try:
                await _ddo.orchestrate_dd(
                    target=body, llm=llm, mode=mode, trace_id=trace_id,
                    user_id=_req_user_id, user_email=_req_user_email,
                    share_to_company=_share_to_company, run_id=_run_id,
                )
            except Exception as _e:  # noqa: BLE001 — recorded as a terminal 'failed' status
                _log.exception("async dd_orchestrate failed for %s: %s", _run_id, _e)
                await _ddo.mark_dd_failed(_run_id, str(_e))

        asyncio.create_task(_bg_dd())
        return {
            "run_id": _run_id,
            "status": "running",
            "async_mode": True,
            "entity_name": _ent,
            "poll_url": f"/api/aria/dd/report/{_run_id}",
            "message": f"Due diligence started for {_ent}. Poll the report URL for the result.",
        }

    try:
        from ..intel import dd_orchestrator
        # R-F2835 — the web route consumed a quota unit before proxying here
        # (server.mjs:3546); charging again would double-count.
        report = await dd_orchestrator.orchestrate_dd(
            target=body,
            llm=llm,
            mode=mode,
            trace_id=trace_id,
            user_id=_req_user_id,
            user_email=_req_user_email,
            share_to_company=_share_to_company,
            quota_charged=True,
        )
    except ValueError as e:
        raise HTTPException(status_code=400, detail=str(e))
    except RuntimeError as e:
        raise HTTPException(status_code=503, detail=str(e))
    except Exception as e:
        _log.exception("dd_orchestrate failed: %s", e)
        raise HTTPException(status_code=500, detail=f"dd_orchestrate error: {e}")

    try:
        await trace_stream.finish_trace(
            trace_id,
            response=f"ARK-DD {report.risk_classification}",
            tool_used="dd_orchestrator",
            status="ok" if report.risk_classification != "HARD_STOP" else "hard_stop",
        )
    except Exception:
        pass

    if output_format == "markdown":
        # R-F1786: offload sync CPU render off the event loop.
        _md = await asyncio.to_thread(report.render_markdown, concise=False)
        return {
            "run_id": report.run_id,
            "risk": report.risk_classification,
            "markdown": _md,
        }
    return report.as_dict()


def _dd_report_access_allowed(report: dict, user_id: str, user_email_domain: str = "",
                              *, destructive: bool = False) -> bool:
    """R-F2291 — who may VIEW / DELETE a DD report by id.

    Mirrors the LIST view's sharing (R-F607/R-F608, dd_orchestrator.list_reports):
    a report is accessible to its OWNER, or to a same-email-domain colleague when
    the report is company-shared (``share_to_company`` != False). Admin /
    autonomous / unscoped callers pass user_id='' and are allowed. Cross-COMPANY
    access stays blocked (R-F1820).

    Before R-F2291 the by-id GET/DELETE used an owner-EXACT check, so a same-
    company colleague opening a SHARED report got 404 — the report body was empty
    ("no content on click") and delete failed (2026-07-02 operator report). The
    list already shares same-domain, so view/delete-by-id must match it.
    """
    if not user_id:
        # R-F2778 (R-F2138 residual) — an EXTERNAL user-facing API-token caller with
        # no user_id must NOT read/delete an arbitrary report by id. Only the INTERNAL
        # service token (WA/web/CLI/autonomous) keeps the unrestricted admin path. This
        # mirrors _dd_owned_entity_ids; without it, the by-id GET/DELETE fell open for
        # external tokens even after the list view was scoped.
        #
        # R-F3800 — the rest of this note used to read "_auth_is_internal_var defaults
        # True for auth-bypass callers (tests / public-bypass), so their behaviour is
        # unchanged". That is NO LONGER TRUE and was the most dangerous sentence here:
        # R-F3628 flipped `_AUTH_INTERNAL_DEFAULT` to False precisely because a True
        # default GRANTS to any context where the setter never ran. A caller that does
        # not declare the internal tier is now DENIED, which is the point. Do not
        # "restore" the old default to make an inheriting test green — that reopens the
        # cross-tenant by-id read/delete for every external token.
        if not _auth_is_internal_var.get():
            return False
        # R-F3709 — an unscoped DESTRUCTIVE call needs the OPERATOR tier.
        #
        # The unscoped branch exists so trusted services can read without a
        # user_id. Deleting is different in kind: `DELETE /dd/report/{run_id}`
        # cascades over entity_group_run_ids and can remove reports owned by
        # OTHER tenants, so a leaked service credential would be a cross-tenant
        # evidence-wipe key. One such credential was committed to this repo for
        # months (scripts/verify_all.py, R-F3683), which is not a hypothetical.
        #
        # Read stays available to the internal service token; only the
        # destructive path is raised to operator.
        if destructive and not _auth_is_operator_var.get():
            return False
        return True  # internal / autonomous / no-filter path
    owner = (report.get("user_id") or "").strip()
    if owner:
        if owner == user_id:
            return True  # owner match
        caller_domain = (user_email_domain or "").strip().lower()
        rep_domain = (report.get("user_email_domain") or "").strip().lower()
        # R-F2777 — never domain-share across a PUBLIC WEBMAIL domain. Two strangers
        # on gmail.com are not one company, so a company-shared report must NOT be
        # visible to another free-webmail user by id (mirrors list_reports).
        from ..intel.dd_orchestrator import _is_public_webmail_domain
        return bool(
            caller_domain and rep_domain and caller_domain == rep_domain
            and not _is_public_webmail_domain(caller_domain)
            and report.get("share_to_company", True) is not False
        )
    # R-F2402 — OWNER-LESS report + a scoped requester: FAIL CLOSED (was fail-open:
    # `if not owner: return True` let ANY authenticated user read/download an
    # owner-less report by id — a GDPR cross-tenant leak, live-confirmed HTTP 200
    # for a stranger). An owner-less report (e.g. a vault-rebuilt legacy report
    # before the R-F2393 index reclaim has healed ownership) must NOT be visible to
    # an arbitrary user. Allow ONLY the configured legacy operator (the sole tenant
    # that has explicitly claimed legacy owner-less DDs via ARIA_DD_LEGACY_OWNER_UID,
    # mirroring the R-F2393 adoption). With that env unset → nobody scoped may read
    # an owner-less report (fail-closed default); admin/internal still uses the
    # user_id='' bypass above.
    import os as _os
    _legacy = (
        (_os.getenv("ARIA_DD_LEGACY_OWNER_UID") or "").strip()
        or (_os.getenv("ARIA_CODER_OPERATOR_USER_ID") or "").strip()
    )
    return bool(_legacy and user_id == _legacy)


async def _dd_report_acl_context(dd_orchestrator, run_id: str, report: dict) -> dict:
    """R-F2291 — build the ownership context for the ACL check by overlaying the
    INDEX entry (authoritative user_id / user_email_domain / share_to_company)
    onto the report body. The body can carry user_id but a None domain; the index
    has the real domain (it's what list_reports + the 'shared' badge read). Index
    wins; the body is the fallback when the run_id has aged out of the index cap.
    """
    acl = dict(report)
    try:
        owner = await dd_orchestrator.get_report_owner(run_id)
    except Exception:
        owner = None
    if owner:
        for k in ("user_id", "user_email_domain", "share_to_company"):
            v = owner.get(k)
            if v is not None:
                acl[k] = v
    return acl


@router.get("/dd/report/{run_id}")
@fail_wire(module="aria", gap_type="engine_failure")
async def dd_report_ep(run_id: str, format: str = "json", user_id: str = "",
                       user_email_domain: str = ""):
    from ..intel import dd_orchestrator
    report = await dd_orchestrator.get_report(run_id)
    if not report:
        raise HTTPException(status_code=404, detail=f"report not found: {run_id}")
    # R-F1820 + R-F2291: owner OR same-company-shared may view (404 to avoid
    # leaking existence otherwise). Node pins user_id + user_email_domain from the
    # JWT so the client cannot forge them. Ownership is read from the INDEX (the
    # authoritative source the list uses) via _dd_report_acl_context — the report
    # BODY can have user_email_domain=None and would 404 a same-company colleague.
    _acl = await _dd_report_acl_context(dd_orchestrator, run_id, report)
    if not _dd_report_access_allowed(_acl, user_id, user_email_domain):
        raise HTTPException(status_code=404, detail=f"report not found: {run_id}")
    if format == "markdown":
        from ..intel import dd_schema
        # R-F1847: if the stored report already has a rendered markdown, use it
        _rendered = report.get("rendered") or report.get("synthesis", {}).get("rendered_markdown", "")
        if _rendered:
            return {"run_id": run_id, "markdown": _rendered}
        try:
            rebuilt = _rebuild_report_from_dict(report, dd_schema)
            _md = await asyncio.to_thread(rebuilt.render_markdown, concise=False)  # R-F1786
            return {"run_id": run_id, "markdown": _md}
        except Exception as e:
            _log.debug("dd report markdown rebuild failed (falling back to raw): %s", e)
    if format == "structured":
        # R-F2331 — decision-first, evidence-rich render contract for the web report
        # page. Built from the persisted structured dict (NOT re-parsed markdown), so
        # each finding keeps its detail / source / confidence / citations.
        from ..intel import dd_schema
        try:
            return {"run_id": run_id, "structured": dd_schema.structured_view(report)}
        except Exception as e:
            _log.debug("dd report structured view failed (falling back to raw): %s", e)
            return report
    if format == "download":
        from ..intel import dd_schema
        from starlette.responses import Response as _Resp
        try:
            rebuilt = _rebuild_report_from_dict(report, dd_schema)
            md = await asyncio.to_thread(rebuilt.render_markdown, concise=False)  # R-F1786
            entity = report.get("identity", {}).get("entity_name", run_id)
            filename = f"dd_report_{entity}_{run_id[:8]}.md".replace(" ", "_").lower()
            return _Resp(
                content=md,
                media_type="text/markdown",
                headers={"Content-Disposition": f'attachment; filename="{filename}"'},
            )
        except Exception as e:
            _log.debug("dd report download failed (falling back to raw): %s", e)
            return _Resp(
                content=str(report),
                media_type="application/json",
                headers={"Content-Disposition": f'attachment; filename="dd_report_{run_id[:8]}.json"'},
            )
    return report


@router.get("/dd/reports")
@fail_wire(module="aria", gap_type="engine_failure")
async def dd_reports_index_ep(
    limit: int = 50,
    user_id: str = "",
    user_email_domain: str = "",
):
    """List recent DD runs.

    R-F607 / R-F608 (2026-05-16): when `user_id` is provided, only that
    user's own runs are returned. When `user_email_domain` is provided
    too, runs from other users on the same email domain are also
    included (unless they explicitly opted out via share_to_company).
    Pre-R-F607 entries (user_id=None on the index row) are hidden from
    user-filtered lists — admin / autonomous paths leave both filters
    empty to see everything.

    R-F1489: when the index is empty this returns an empty list and the UI shows
    an honest "No DD reports yet" empty-state. (The earlier R-F1484 auto-seed,
    which fabricated a sample report into the real store, was removed — never
    seed fake findings on a compliance product or ARIA learns from them.)
    """
    from ..intel import dd_orchestrator
    # R-F2778 (R-F2138 residual) — an EXTERNAL user-facing API-token caller with no
    # user_id must NOT receive every tenant's reports (list_reports' admin no-filter
    # path). Only the INTERNAL service token keeps that unrestricted path. Mirrors the
    # _dd_owned_entity_ids / _dd_report_access_allowed fail-closed. _auth_is_internal_var
    # defaults True for auth-bypass callers (tests / public-bypass) — unchanged there.
    if not (user_id or "").strip() and not _auth_is_internal_var.get():
        return {"reports": []}
    reports = await dd_orchestrator.list_reports(
        limit=limit,
        user_id=user_id or None,
        user_email_domain=user_email_domain or None,
    )
    # R-F1489: REMOVED the R-F1484 auto-seed. It fabricated a full "Acme Defence
