@router.get("/dd/health")
@fail_wire(module="aria", gap_type="engine_failure")
async def dd_health_ep():
    """R-F1914: DD system health - per-layer completion rates and error counts.

    Reads layer stats recorded by _finalize_dd_run() in dd_orchestrator.py.
    Returns the number of runs, successes, and errors per layer over the
    last 7 days. Lets the operator see at a glance which DD layers are
    healthy and which are silently failing.
    """
    from ..intel import redis_store as rs

    # R-F3359 — the layer vocabulary is owned by the PRODUCER
    # (dd_orchestrator.DD_LAYER_NAMES). This list used to be re-typed here and
    # had drifted both ways: it carried `extensions` (never a layer) and was
    # missing `forensic` + `deterministic_primitives` (which run on every DD),
    # so two real layers could not appear on this surface at all.
    from ..intel.dd_orchestrator import (
        DD_LAYER_NAMES as _DD_LAYER_NAMES,
        DD_LAYER_STATS_WINDOW_DAYS as _DD_WINDOW_DAYS,
        get_layer_stats_window as _layer_window,
    )

    # R-F3364 — sum the day-buckets so "last 7 days" is a MEASURED window. The
    # old flat key had its TTL refreshed on every write, so it never expired and
    # this surface reported all-time totals under a 7-day label: the digital
    # layer still read 52% error three days after R-F3059/R-F3066 fixed the
    # cause, and any new regression would have been diluted by that history.
    layers = {}
    for layer_name in _DD_LAYER_NAMES:
        try:
            layers[layer_name] = await _layer_window(layer_name)
        except Exception:
            layers[layer_name] = {"error": "unreachable"}

    total_runs = sum(
        sum(v.values()) for v in layers.values() if isinstance(v, dict)
    )
    total_errors = sum(
        v.get("error", 0) + v.get("timeout", 0)
        for v in layers.values() if isinstance(v, dict)
    )

    return {
        "layers": layers,
        "total_runs": total_runs,
        "total_errors": total_errors,
        "error_rate_pct": round(total_errors / total_runs * 100, 1) if total_runs > 0 else 0,
        # R-F3364 — state the window that was actually measured. The previous
        # payload implied "7 days" in its docstring while serving all-time counts.
        "window_days": _DD_WINDOW_DAYS,
    }


@router.get("/dd/layer-5c/digital-stats")
@fail_wire(module="aria", gap_type="engine_failure")
async def dd_layer_5c_digital_stats_ep(limit: int = 200):
    """R-F1506: Layer 5C (digital footprint) stats for the brain command center.

    R-F2278 (2026-07-02): renamed from `/dd/layer-5c/stats` (fn was
    `dd_layer_5c_stats_ep`) — it COLLIDED with the commercial-coherence handler
    of the same path/name defined earlier (line ~1112). FastAPI served that
    earlier handler, so this digital-footprint variant was dead code. The live
    consumer (aria-brain.html loadLayer5c → by_tier/runs_scanned) reads the
    commercial-coherence shape, so THAT one keeps the canonical path; this
    variant is renamed to preserve it without shadowing. No live consumer read
    this path.

    Returns aggregate stats about digital-layer DD runs: how many entities
    have been scanned, how many have web presence data, certificate transparency
    hits, social media profiles, etc.
    """
    from ..intel import dd_orchestrator as _do
    try:
        reports = await _do.list_reports(limit=limit)
    except Exception:
        reports = []
    total = len(reports)
    with_web = 0
    with_ct = 0
    with_social = 0
    for r in reports:
        ext = r.get("extensions") or {}
        # R-F2409 — `ext.get("by_module")` can be an explicit None (key present,
        # value null), so guard with `or {}`; the bare version 500'd this endpoint
        # with AttributeError: 'NoneType' object has no attribute 'get'.
        by_mod = (ext.get("by_module") or {}) if isinstance(ext, dict) else {}
        if by_mod.get("cert_transparency"):
            with_ct += 1
        if r.get("digital"):
            with_web += 1
    return {
        "total_entities_scanned": total,
        "with_web_presence": with_web,
        "with_cert_transparency": with_ct,
        "with_social_media": with_social,
        "recent_limit": limit,
    }


# ── R-F1182: VLS (Verifiable Ledger System) endpoints ──────────────────────


async def _dd_vls_run_access_ok(dd_orchestrator, run_id: str, user_id: str,
                                user_email_domain: str) -> bool:
    """R-F2588 — may this caller read VLS proof/verify for `run_id`?

    Mirrors the by-id report ACL (dd_report_delete_ep): owner or same-company
    shared, admin/internal (user_id='') always. A SCOPED caller whose run_id
    maps to no known report fails CLOSED (don't reveal proof existence for an
    unknown/unowned run_id — run_id is random so not enumerable, but we still
    never confirm existence to a stranger). Internal (user_id='') is allowed
    through so server-to-server verification keeps working.
    """
    _report = await dd_orchestrator.get_report(run_id)
    if _report is not None:
        _acl = await _dd_report_acl_context(dd_orchestrator, run_id, _report)
        return _dd_report_access_allowed(_acl, user_id, user_email_domain)
    return not user_id  # unknown run_id: internal→allow, scoped→deny (fail closed)


@router.get("/dd/vls/proof/{run_id}")
@fail_wire(module="aria", gap_type="engine_failure")
async def dd_vls_proof_ep(run_id: str, user_id: str = "", user_email_domain: str = ""):
    """R-F1182 — retrieve the VLS cryptographic proof for a DD report.

    Returns the proof (hash, signature, chain link) or 404 if no proof
    exists (pre-VLS reports, or the proof was never stored).

    R-F2588 — ownership gate (confirmed cross-tenant IDOR: existence + chain
    metadata leak by run_id). Only the owner / same-company colleague / internal
    caller may read a report's proof; everyone else 404s.
    """
    from ..intel import dd_orchestrator
    from ..intel import verifiable_ledger as _vls
    if not await _dd_vls_run_access_ok(dd_orchestrator, run_id, user_id, user_email_domain):
        raise HTTPException(status_code=404, detail=f"No VLS proof found for run_id={run_id}")
    proof = await _vls.get_proof(run_id)
    if not proof:
        raise HTTPException(status_code=404, detail=f"No VLS proof found for run_id={run_id}")
    return {"run_id": run_id, "proof": proof}


