# ── R-F1771 — external eval-result sink (pod-self-run eval, no client SSH) ──
# A self-running RunPod eval pod (eval_selfrun_v07.sh) serves the on-volume
# adapter, runs the 500-Q eval, then POSTs its judge-DD result HERE; we read it
# via GET. This removes the Windows RunPod-SCP transport dependency entirely —
# the result comes OUT of the pod to the brain instead of us pulling it over SSH.
_EVAL_EXTERNAL_KEY = "crucix:aria:eval:external:latest"


@router.post("/eval/external-result")
@fail_wire(module="aria", gap_type="engine_failure")
async def eval_external_result_post_ep(request: Request):
    """Receive a judge-DD eval result POSTed by a self-running eval pod."""
    try:
        body = await request.json()
    except Exception:
        body = {}
    if not isinstance(body, dict):
        body = {}
    import time as _t1771
    record = {
        "model": str(body.get("model") or "")[:80],
        "accuracy": body.get("accuracy"),
        "leak_rate": body.get("leak_rate"),
        "n": body.get("n"),
        "label": str(body.get("label") or "")[:160],
        "report": body.get("report"),  # optional full report dict
        "received_at": _t1771.time(),
        "source": str(body.get("source") or "runpod_selfrun")[:60],
    }
    try:
        await rs.set_json(_EVAL_EXTERNAL_KEY, record, ex=30 * 86400)
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"store failed: {e}")
    return {"ok": True, "stored": {k: record.get(k) for k in ("model", "accuracy", "leak_rate", "n")}}


@router.get("/eval/external-result")
@fail_wire(module="aria", gap_type="engine_failure")
async def eval_external_result_get_ep():
    """Read the latest external eval result (what the self-run pod POSTed)."""
    rec = await rs.get_json(_EVAL_EXTERNAL_KEY)
    return {"result": rec, "present": rec is not None}


# ── R-F1773 — UNIVERSAL deploy-intent ledger sink ───────────────────────
# A git pre-push hook POSTs every push's HEAD sha here BEFORE the deploy can be
# claimed done. The proprioception loop (main.py) then verifies each intent
# actually went live → deploy_verification_failure gap if it never did. Closes
# the confabulation hole that a RAW `git push` (R-F1770) slipped through — no
# deploy path can claim "deployed" without machine proof anymore.
@router.post("/deploy/intent")
@fail_wire(module="aria", gap_type="engine_failure")
async def deploy_intent_post_ep(request: Request):
    """Record a deploy-intent (commit_sha + source) for live verification."""
    try:
        body = await request.json()
    except Exception:
        body = {}
    if not isinstance(body, dict):
        body = {}
    sha = str(body.get("commit_sha") or body.get("sha") or "").strip()
    if not sha:
        raise HTTPException(status_code=400, detail="commit_sha required")
    source = str(body.get("source") or "pre_push_hook")[:60]
    from ..autonomous import deploy_verifier as _dv1773
    try:
        intents = await rs.get_json(_dv1773.DEPLOY_INTENTS_KEY) or []
    except Exception:
        intents = []
    updated = _dv1773.add_deploy_intent(intents, sha, source)
    try:
        await rs.set_json(_dv1773.DEPLOY_INTENTS_KEY, updated, ex=30 * 86400)
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"store failed: {e}")
    return {"ok": True, "recorded": sha[:8], "source": source, "pending": len(updated)}


@router.get("/deploy/intents")
@fail_wire(module="aria", gap_type="engine_failure")
async def deploy_intents_get_ep():
    """List the deploy-intent ledger (verified + pending) for proprioception."""
    from ..autonomous import deploy_verifier as _dv1773
    try:
        intents = await rs.get_json(_dv1773.DEPLOY_INTENTS_KEY) or []
    except Exception:
        intents = []
    if not isinstance(intents, list):
        intents = []
    pending = [i for i in intents if isinstance(i, dict) and not i.get("verified_live")]
    return {"intents": intents, "total": len(intents), "pending": len(pending)}


# ── R-F1774 — brain-served openbook eval set (compute-pod transport) ─────
# The 500-Q openbook eval set lives in the repo (data/eval_reports/), which is NOT
# in the deployed image and NOT reliably on the RunPod volume — and Windows RunPod
# SCP/SSH drops, so we can't push it pod-side. Instead: PUT it here once (from any
# box) and the self-run eval pod GETs it over the SAME authenticated channel it
# already uses. No SCP, no git-auth dependency on the pod.
_EVAL_OPENBOOK_KEY = "crucix:aria:eval:openbook:set"


@router.post("/eval/openbook-set")
@fail_wire(module="aria", gap_type="engine_failure")
async def eval_openbook_set_post_ep(request: Request):
    """Store the openbook eval set (raw JSONL body) for compute pods to fetch."""
    body = await request.body()
    text = body.decode("utf-8", "replace")
    lines = [ln for ln in text.splitlines() if ln.strip()]
    if not lines:
        raise HTTPException(status_code=400, detail="empty body")
    try:
        await rs.set(_EVAL_OPENBOOK_KEY, "\n".join(lines), ex=30 * 86400)
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"store failed: {e}")
    return {"ok": True, "lines": len(lines), "bytes": len(text)}


@router.get("/eval/openbook-set")
@fail_wire(module="aria", gap_type="engine_failure")
async def eval_openbook_set_get_ep():
    """Return the stored openbook eval set as JSONL (the pod writes it to disk)."""
    from fastapi.responses import PlainTextResponse
    text = await rs.get(_EVAL_OPENBOOK_KEY)
    if not text:
        raise HTTPException(status_code=404, detail="no eval set stored")
    return PlainTextResponse(content=text, media_type="application/x-ndjson")


