class RagIngestRequest(BaseModel):
    text: str
    source: str
    source_type: str = "manual"
    title: str = ""
    url: str = ""
    market: str = ""
    # R-F3488 — the data-subject envelope, declarable at the boundary that takes
    # "customer document drops". A drop about an identified person is personal data;
    # without a subject key it can never be erased on request, only swept best-effort.
    # Optional so no existing caller breaks, and an unkeyed personal-data write is
    # recorded as a gap rather than silently accepted.
    data_subject_key: str = ""
    lawful_basis: str = ""
    retention_class: str = ""
    # R-F3492 — whose law governs this record. Retention period and residency both
    # depend on it, and it is NOT inferable from the storage region.
    data_jurisdiction: str = ""
    personal_data: bool = False


@router.post("/rag/ingest")
@fail_wire(module="aria", gap_type="engine_failure")
async def rag_ingest_ep(req: RagIngestRequest):
    """Manually ingest a document into the RAG store. Used for backfill,
    customer document drops, and any text the team wants ARIA to remember.
    """
    if not req.text or len(req.text.strip()) < 50:
        raise HTTPException(status_code=400, detail="text required (min 50 chars)")
    return await rag_store.ingest_document(
        text=req.text,
        source=req.source,
        source_type=req.source_type,
        title=req.title,
        url=req.url,
        market=req.market,
        data_subject_key=req.data_subject_key,
        lawful_basis=req.lawful_basis,
        retention_class=req.retention_class,
        data_jurisdiction=req.data_jurisdiction,
        personal_data=req.personal_data,
    )


