# ── NLU: detect investigative intent in free-form text ──────────────────────
_URL_RE = re.compile(r"https?://[^\s<>\"'\]\)]+", re.IGNORECASE)
_DOMAIN_RE = re.compile(r"\b(?:[a-z0-9-]+\.)+(?:com|co\.uk|org|net|gov|edu|io|ai|de|fr|pt|es|br|mz|ao|cv|ke|ng|za|cn|ru)(?:/\S*)?", re.IGNORECASE)

# Imperative verbs (and noun equivalents) that signal "go do something"
# rather than "answer me from training data". The noun forms were added
# 2026-04-09 19:38 after the DUMA Engineering incident: the user said
# "Aria, investigation https://duma-engineering.com?" (noun, not verb)
# and the regex missed it, so the chain fell through to route 3
# (extract_url, single page) instead of route 2 (deep_research, 5-angle
# + extracts). The resulting brief only saw the homepage and called
# DUMA a "potential shell entity" because off-site OSINT (Jane's,
# LinkedIn, Crunchbase) was never queried.
_INVESTIGATE_KW = re.compile(
    r"\b("
    r"investigate|investigation|investigations|investigating|"
    r"research|researching|researches|"
    r"look\s+into|looking\s+into|"
    r"dig\s+into|digging\s+into|"
    r"find\s+out\s+about|"
    r"deep[\-\s]?dive|do\s+a\s+deep\s+dive|"
    # Natural phrasings users type instead of "investigate" — all should
    # fire deep_research when combined with a URL. Past incident
    # 2026-04-18: user asked "what do you know about csg.com/en" and
    # intent router fell to the shallow `read` path, which extracted
    # only the homepage. LLM then hallucinated "Jurisdiction: Turkey"
    # off the CSG acronym instead of reading the full extract.
    r"tell\s+me\s+(?:everything\s+)?about|"
    r"tell\s+me\s+what\s+you\s+know|"
    r"what\s+(?:do\s+you\s+know|can\s+you\s+tell\s+me)(?:\s+about)?|"
    r"who\s+is|what\s+is\s+(?!the\s+(?:best|difference|status|cost|price))|"
    r"information\s+(?:on|about)|"
    r"details?\s+(?:on|about)|"
    r"describe\s+(?:this|that|the)?|"
    r"explore|exploring|"
    r"due\s+diligence|"
    r"DD\s+(?:on|of)|"
    r"background\s+check"
    r")\b",
    re.IGNORECASE,
)
_CRAWL_KW       = re.compile(r"\b(crawl|spider|scrape|harvest)\b", re.IGNORECASE)
_READ_KW        = re.compile(r"\b(read|fetch|grab|pull\s+in|ingest|summari[sz]e\s+(?:this|the)\s+(?:url|page|article|link))\b", re.IGNORECASE)
_PROFILE_KW     = re.compile(r"\b(profile|build\s+a\s+profile\s+on|background\s+check|due\s+diligence\s+on)\b", re.IGNORECASE)
# R-F793 (2026-05-22) — doc-reference detector. When the user attached
# a document (the chat UI embeds it as [ATTACHED DOCUMENT … /ATTACHED
# DOCUMENT] in the message text) AND their question explicitly refers
# to the attached artifact, the tool dispatcher should hand off to the
# LLM-pure path so the LLM can read the doc directly — not run an
# external tool whose output replaces the doc context.
_DOC_REFERENCE_RE = re.compile(
    r"\b(?:this|the|that|attached|uploaded)\s+"
    r"(?:document|file|pdf|attachment|report|spreadsheet|"
    r"screenshot|image|paper|letter|email|memo|brief|deck|note|"
    r"nda|agreement|contract|clause|terms|schedule|addendum|"
    r"mou|loi|sow|t[&\s]*cs)\b",
    re.IGNORECASE,
)
# R-F1326 — also match review/feedback verbs referencing an attached doc,
# even when the noun is implicit ("review this", "feedback on the attached").
_DOC_REVIEW_VERB_RE = re.compile(
    r"\b(?:review|feedback|redline|mark\s+up|comment\s+on|assess)\b",
    re.IGNORECASE,
)

# R-F2229 — hoisted to module level (was local inside _detect_tool_intent) so the
# §22a doc-review guard can reference it BEFORE the ungated tool branches
# (registry_lookup / dd_orchestrate / portal_register / pre_meeting_briefing).
# Matches an explicit multi-company doc-investigate ask (R-F1416) — the one doc
# case that KEEPS external-tool precedence over the doc-review skip.
_DOC_INVESTIGATE_RE = re.compile(
    r"\b(?:investigate|research|look\s+into|find\s+out\s+about|"
    r"profile|screen|check\s+out|analyse|analyze|"
    r"tell\s+me\s+about|what\s+(?:do\s+you\s+know|can\s+you\s+tell\s+me))\b"
    r".*?\b(?:companies|company|entities|entity|firms?|"
    r"suppliers?|vendors?|partners?|contractors?|"
    r"each|all|these|every|both)\b",
    re.IGNORECASE | re.DOTALL,
)

# R-F793 (2026-05-22) — removed bare `sanction|` from the alternation.
# Pre-R-F793 the bare noun matched in any context: "the EU sanction packet
# where this rule is implemented" matched at "sanction", entity-extracted
# the entire trailing string (" packet where this rule is implemented…")
# as the "entity", screen tool returned no useful hits, LLM then fell back
# to general-knowledge inference. Legitimate intent stays covered by the
# multi-word forms: `/screen X`, `screen X`, `sanctions check on X`,
# `compliance check`, `fuzzy match`, `fuzzy screen`, `run compliance`.
_SCREEN_KW      = re.compile(r"\b(screen|sanctions\s+check|compliance\s+check|run\s+(?:a\s+)?compliance|fuzzy\s+screen|fuzzy\s+match)\b", re.IGNORECASE)
_PERSON_KW      = re.compile(r"\b(person|individual|director|minister|general|colonel|owner|ceo|cfo)\b", re.IGNORECASE)
_COMPANY_KW     = re.compile(r"\b(company|corporation|firm|business|ltd|limited|inc|gmbh|sa|sarl|ltd\.|plc)\b", re.IGNORECASE)
# New tool keywords introduced with the brain/neuron upgrade
_CONFLICT_KW    = re.compile(r"\b(conflict|kinetic|escalation|violence|attacks?|battles?|insurgency|"
                              r"what(?:'s|\s+is)\s+happening\s+in|situation\s+in|security\s+(?:in|situation)|"
                              r"acled|gdelt)\b", re.IGNORECASE)
_TECH_KW        = re.compile(r"\b(what\s+is\s+(?:a|the)\s+|specs?\s+(?:of|for)\s+|tell\s+me\s+about\s+(?:the\s+)?|"
                              r"classify\s+(?:this|these)|extract\s+items|what\s+ml\s+category)\b", re.IGNORECASE)
_FUZZY_KW       = re.compile(r"\b(fuzzy|alias|alternate\s+spelling|transliteration|name\s+variant)\b", re.IGNORECASE)

# R-F2427 (2026-07-05, Blocker 1) — trailing INTENT/PURPOSE clause.
# Live bug (a99e smoke): "Screen Tactical Missiles Corporation KTRV for
# sanctions" screened the literal word "sanctions", not "KTRV" — the R-F1749
# compliance NLU (`_COMPLIANCE_FOR_RE`) matched the tail "for sanctions" and
# used "sanctions" as the entity. Root cause: the entity-extraction paths grab
# whatever follows the LAST for/on/of/against, so a trailing purpose clause
# ("… for sanctions", "… for adverse media check") is mistaken for the entity.
# This regex matches ONLY a trailing purpose clause whose object is an intent
# noun (sanctions / adverse media / compliance / screening / PEP / AML / …) so
# the real entity (which precedes it) survives. Anchored to end-of-string with
# a bounded suffix set, so a company legitimately named "Compliance Solutions
# Inc" (noun not at end) is NOT stripped.
_INTENT_PURPOSE_TAIL_RE = re.compile(
    r"\s+(?:for|against|regarding|re)\s+"
    r"(?:(?:an?|any|its?|their|possible|potential)\s+)?"
    r"(?:"
    r"sanctions?|sanctioned|"
    r"adverse[\s-]?media|negative\s+news|negative\s+media|"
    r"pep|peps|"
    r"aml|kyc|cft|"
    r"compliance|export[\s-]?controls?|"
    r"watch[\s-]?lists?|"
    r"screening|"
    r"due\s+diligence|"
    r"reputational|reputation|"
    r"financial\s+crime|money\s+laundering"
    r")"
    r"(?:\s+(?:screen(?:ing)?|checks?|exposure|risks?|purposes?|reasons?|"
    r"review|assessment|due\s+diligence|hits?))?"
    r"\s*$",
    re.IGNORECASE,
)

# R-F2428 (2026-07-05, Blocker 2) — adverse-media / negative-news intent.
# Live bug (a99e smoke): "Adverse media check on Wagner Group" matched NO tool
# intent (adverse-media is absent from _COMPLIANCE_KW_RE / _SCREEN_KW /
# _INVESTIGATE_KW) → routed to tool=None → answered from model memory, so
# R-F2426's adverse angles never fired. This detector routes such phrasings to
# deep_research with the adverse signal folded into the entity (R-F2426 flips
# `_adverse_signalled` when the entity phrase carries an adverse term).
_ADVERSE_MEDIA_KW_RE = re.compile(
    r"\b(adverse[\s-]?media|negative\s+news|negative\s+media|"
    r"reputational\s+(?:check|screen(?:ing)?|risk|due\s+diligence|review|profile)|"
    r"negative\s+screening|derogatory\s+(?:information|media|news))\b",
    re.IGNORECASE,
)
# Leading action verb / determiner in front of the adverse keyword when the
# subject precedes it ("run an adverse media check", "screen X for adverse
# media"). Stripped so the bare subject remains.
_ADVERSE_LEAD_VERB_RE = re.compile(
    r"^(?:please\s+|kindly\s+|can\s+you\s+|could\s+you\s+)?"
    r"(?:run|do|perform|conduct|check|screen|give\s+me|get\s+me|pull|fetch|"
    r"provide|show\s+me|carry\s+out)?\s*"
    r"(?:an?|any|the|some)?\s*",
    re.IGNORECASE,
)
_ADVERSE_TRAIL_CONNECTOR_RE = re.compile(
    r"\s+(?:for|on|of|about|against|into|re|regarding)\s*$",
    re.IGNORECASE,
)


def _extract_adverse_subject(msg: str, kw_match: "re.Match") -> str:
    """R-F2428 — pull the real subject out of an adverse-media phrasing.

    Handles both "adverse media check on <X>" (subject after a connector that
    follows the keyword) and "<X> adverse media" (subject precedes the keyword).
    Returns "" when no plausible subject is present (honest no-route, §14)."""
    tail = msg[kw_match.end():]
    m_after = re.search(
        r"\b(?:on|for|of|about|against|into|re|regarding)\s+(.+?)\s*$",
        tail, re.IGNORECASE,
    )
    if m_after and m_after.group(1).strip():
        subj = m_after.group(1)
    else:
        # Subject precedes the keyword — drop a leading action verb/determiner
        # and any trailing connector left dangling ("check X for" → "X").
        subj = _ADVERSE_LEAD_VERB_RE.sub("", msg[:kw_match.start()])
        subj = _ADVERSE_TRAIL_CONNECTOR_RE.sub("", subj)
    subj = subj.strip(" .,:;-?!\"'\n")
    subj = re.sub(r"^(?:on|for|of|about|the|a|an)\s+", "", subj, flags=re.IGNORECASE)
    # Drop a leading interrogative so a definitional "what is adverse media"
    # (no real subject) collapses to "" and honestly falls through to the
    # generic investigate path instead of routing a question as the entity.
    subj = re.sub(
        r"^(?:what(?:'s|\s+is|\s+are)?|why|how|when|where|who|which|"
        r"is|are|does|do|can|could|should|tell\s+me|give\s+me)\b\s*",
        "", subj, flags=re.IGNORECASE,
    )
    return subj.strip(" .,:;-?!\"'\n")

# Phase 3 cherry-pick from aria_research_architecture.py 2026-04-09:
# Procurement / tender intent — fires deep_research with a procurement-
# scoped query. Conservative regex: requires both a procurement noun
# AND a market or year so we don't trigger on every "I had a contract".
_PROCUREMENT_KW = re.compile(
    r"\b(tender|RFP|RFQ|RFI|procurement|concurso|"
    r"public\s+(?:contract|notice)|contract\s+award|"
    r"bid\s+(?:submission|opportunit)|opportunit(?:y|ies)\s+for|"
    r"request\s+for\s+(?:proposal|quote|information))\b",
    re.IGNORECASE,
)

# Time-sensitive trigger — when the user uses a temporal word the answer
# is almost always going to be wrong from training data alone, so we
# should fire deep_research instead of trusting the LLM's stale memory.
# Past incidents driving this: officeholder hallucinations (Nitiwul/Ghana),
# stale conflict casualty figures, expired sanctions designations.
_TIME_SENSITIVE_KW = re.compile(
    r"\b(current(?:ly)?|latest|recent(?:ly)?|today|this\s+week|"
    r"this\s+month|right\s+now|these\s+days|as\s+of|2025|2026|2027|"
    r"in\s+the\s+last\s+\d+\s+(?:days?|weeks?|months?))\b",
    re.IGNORECASE,
)

# Internal-composition detector — added 2026-04-21. Prompts asking ARIA to
# COMPOSE a digest / briefing / report / summary are internal tasks that
# belong on the pure-LLM path (which already has sweep + intel_ledger +
# memory context injected by aria_engine). They should never fire
# deep_research — the web_search angles would be searching for the prompt
# itself, not facts.
_COMPOSE_VERB_RE = re.compile(
    r"\b(generate|produce|create|compose|draft|prepare|"
    r"give\s+me|send\s+me|write\s+me|build\s+me)\b",
    re.IGNORECASE,
)
_COMPOSE_NOUN_RE = re.compile(
    r"\b(digest|briefing|brief|summary|report|recap|bulletin|"
    r"intelligence\s+(?:digest|briefing|report|update)|"
    r"morning\s+(?:digest|brief|update)|"
    r"daily\s+(?:digest|brief|update))\b",
    re.IGNORECASE,
)
_FORMAT_DIRECTIVE_RE = re.compile(
    r"\b(format\s+for|max\s+\d+\s+lines?|in\s+table\s+form|"
    r"bullet\s+points?|numbered\s+list|telegram|whatsapp)\b",
    re.IGNORECASE,
)
_NUMBERED_SECTION_RE = re.compile(r"^\s*\d+\.\s+", re.MULTILINE)

# Brave Answers fast-path triggers (added 2026-04-21). The trigger matches
# messages that START with a question word + linking verb, so prose with
# embedded "what is" ("tell me about what is happening in angola") doesn't
# false-fire. The exclude pattern keeps heavier specialised paths (DD,
# compliance, composition, meta_query) on their existing routes.
_BRAVE_QA_TRIGGER_RE = re.compile(
    r"^\s*(aria[,\s]+|please\s+|kindly\s+|can\s+you\s+|could\s+you\s+)*"
    r"(what|who|when|where|why|how\s+(?:many|much|long|old|big|tall|far))\s+"
    r"(is|are|was|were|did|does|do|has|have|had)\b",
    re.IGNORECASE,
)
# ── RECENCY IS A TRIGGER IN ITS OWN RIGHT ────────────────────────────────────
#
# The trigger above requires a question word FOLLOWED BY a linking verb, and
# admits `how` only before many/much/long/old/big/tall/far — a deliberate dodge
# for "how are you". The cost of that narrowing is that every "how is/are the
# <thing>" question falls through to no tool at all.
#
# MEASURED, live WhatsApp 2026-08-04 09:09:
#   operator: "How is the fires in Madrid and Bordeaux?"
#   ARIA:     "I don't have live news or real-time incident data in front of me
#              right now, so I'm not going to guess."
#
# She has Brave. It answered DD queries forty minutes earlier. The message never
# reached a tool, so the engine answered from static knowledge — and the reply is
# honest about what it was handed while being wrong about what she can do. She
# even offered: "Want me to pull a current situation brief?" She could have.
#
# Probed against the live detector, all returning NO TOOL:
#   "How are the fires in Madrid and Bordeaux?"
#   "latest news on the Bordeaux fires"
#   "what's the current situation with wildfires in Spain"
# while "what is happening with the wildfires in Madrid" routed correctly. The
# difference is phrasing, not need. "latest news on X" returning no tool is the
# clearest tell: the word `latest` is the entire point of the question.
#
# The property that decides whether a web call is warranted is RECENCY — is the
# answer something that changed since training — not whether the sentence opens
# with an approved verb pair. This matches on that instead.
#
# `how\s+(?:is|are)\s+the\b` REQUIRES the article, so "how are you" and "how are
# things" still fall through. All four existing exclusions (specialist tools,
# ambient clock, self-infrastructure, length) apply unchanged, so nothing that
# was deliberately kept off Brave moves onto it.
_BRAVE_QA_RECENCY_RE = re.compile(
    r"("
    r"\b(?:latest|current|currently|ongoing|unfolding)\b"
    r"|\bright\s+now\b|\bat\s+the\s+moment\b|\bso\s+far\b"
    r"|\b(?:today|tonight|this\s+(?:morning|afternoon|evening|week))\b"
    r"|\b(?:any\s+)?(?:update|news|latest)\s+(?:on|about|from)\b"
    r"|\bwhat'?s\s+(?:happening|going\s+on|the\s+situation)\b"
    r"|\bsituation\s+(?:in|with|around|on)\b"
    r"|\bstill\s+(?:burning|ongoing|active|going|closed|open)\b"
    r"|\bhow\s+(?:is|are)\s+the\b"
    r")",
    re.IGNORECASE,
)
_BRAVE_QA_EXCLUDE_RE = re.compile(
    r"\b(dd|due\s+diligence|investigate|screen|sanction|compliance|"
    r"memory\s+status|brain\s+stats|your\s+(?:memory|status|email|brain)|"
    r"meta[\s_-]?query|fuzzy\s+sanctions?|"
    # 2026-04-21: email-recall questions ("what was in my email") must
    # NOT route to Brave Answers — they belong in meta_query where the
    # RAG email-search actually runs. Brave would return a generic
    # "no email content available" cached answer and ARIA narrates it
    # as if emails are missing.
    r"(?:my|the|test|recent|last)\s+(?:email|inbox|message)|"
    r"email\s+(?:content|body|text)|"
    r"(?:quote|show\s+me)\s+(?:the\s+)?email)\b",
    re.IGNORECASE,
)

# 2026-04-25: self-introspection detection moved to shared module
# `aria_service/intel/self_infra_detector.py`. Imported below; alias kept
# for compatibility with existing test references.
from ..intel.self_infra_detector import SELF_INFRA_INTROSPECTION_RE as _BRAVE_QA_SELF_INFRA_RE

# R-F3592 — questions ARIA answers from her OWN CURRENT CONTEXT block (R-F3588),
# which must never be routed to a paid web search.
#
# Deliberately NARROW. It matches only a request for the CURRENT instant:
#   "what time is it", "what is the time in Portugal", "what's the date today",
#   "what day is it", "what year is it", "current time in Lisbon"
# It must NOT swallow genuine web questions that merely contain a time word:
#   "what time does the LSE open", "when did the sanctions take effect",
#   "what is the deadline for SITCL applications"
# — those need sources, and over-excluding would send ARIA to answer them from
# training data, which is the fabrication this product exists to avoid.
_BRAVE_QA_AMBIENT_RE = re.compile(
    r"("
    r"\bwhat(?:'s|\s+is|\s+was)?\s+the\s+(?:current\s+)?(?:time|date|day|year)\b"
    r"(?!\s+(?:zone|limit|frame|line))"
    r"|\bwhat\s+time\s+is\s+it\b"
    r"|\bwhat\s+day\s+is\s+it\b"
    r"|\bwhat\s+year\s+is\s+it\b"
    r"|\bcurrent\s+(?:local\s+)?(?:time|date)\b"
    r"|\btime\s+(?:right\s+)?now\b"
    r"|\btoday'?s\s+date\b"
    r")",
    re.IGNORECASE,
)


def _looks_like_internal_composition(msg: str) -> bool:
    """Detect 'compose me a digest' prompts that must NOT route to deep_research.

    Triggers when the message shows at least TWO of:
      - compose verb (generate/produce/create/…)
      - composition noun (digest/briefing/report/…)
      - multi-section instruction (≥2 numbered sections)
      - format directive (format for Telegram, max N lines)

    Two-of-four keeps the false-positive rate down: a single "write me
    an update" with no structure is ambiguous and should still flow to
    the normal classifier. A prompt with sections AND a format
    directive is unmistakably an internal composition task.
    """
    signals = 0
    if _COMPOSE_VERB_RE.search(msg):
        signals += 1
    if _COMPOSE_NOUN_RE.search(msg):
        signals += 1
    if len(_NUMBERED_SECTION_RE.findall(msg)) >= 2:
        signals += 1
    if _FORMAT_DIRECTIVE_RE.search(msg):
        signals += 1
    return signals >= 2
# Known weapon systems - matched against tech_classifier's database
_WEAPON_DESIGNATION_RE = re.compile(
    r"\b(F[\-/]?\d{1,3}|Su[\-/]?\d{1,3}|MiG[\-/]?\d{1,3}|MQ[\-/]?\d|TB\d|"
    r"K9|HIMARS|Caesar|PzH\s*2000|M777|Patriot|S[\-]?[34]00|Iron\s+Dome|NASAMS|"
    r"IRIS[\-/]?T|THAAD|Javelin|Spike|NLAW|Stinger|BrahMos|Storm\s+Shadow|SCALP|"
    r"Harpoon|Exocet|NSM|Leopard\s*2|Abrams|Challenger|Bayraktar)\b",
    re.IGNORECASE,
)
# Country detection (re-uses ACLED ISO map)
_COUNTRY_RE_TOOL = re.compile(
    r"\b(angola|mozambique|guinea[\-\s]bissau|cape\s+verde|nigeria|kenya|mali|"
    r"burkina\s+faso|niger|chad|sudan|ethiopia|somalia|cameroon|senegal|drc|"
    r"ghana|south\s+africa|libya|egypt|iraq|syria|yemen|afghanistan|ukraine|russia|"
    r"saudi\s+arabia|uae|jordan|lebanon|colombia|venezuela|haiti|myanmar)\b",
    re.IGNORECASE,
)

# DD orchestrator intent detection — fires the 7-layer dd_orchestrator
# when the user explicitly asks for a due-diligence run on a named
# entity. Accepted forms:
#   "full DD on Baykar Technology"
#   "run due diligence on ACME Corp"
#   "investigate ACME Corp as a counterparty"
#   "DD report on Rosoboronexport"
#   "ark-dd on Lockheed Martin"
#   "orchestrate DD on Baykar"
# The intent is intentionally narrower than "investigate X" alone,
# because investigate already has an existing deep_researcher path.
# "DD" / "due diligence" / "ark-dd" / "dd report" are the trigger keys.
_DD_INTENT_RE = re.compile(
    r"(?:"
    r"\b(?:full\s+|comprehensive\s+|ark[\-_]?)?p?dd(?:\s+report)?\b|"
    r"\bdue\s+diligence\b|"
    r"\bark[\-_]?(?:p)?dd\b|"
    r"\bperson\s+(?:dd|due\s+diligence)\b|"
    r"\bbackground\s+(?:dd|check)\b|"
    r"\bpep\s+(?:check|screen)\b|"
    r"\brun\s+a?\s*(?:full\s+)?(?:background|compliance|dd|pdd)\s+(?:check|report)\b|"
    r"\borchestrate\s+(?:p)?dd\b|"
    r"\b(?:profile|dossier)\s+on\s+|"
    # R-F729 (2026-05-20) — natural-language DD intent extensions.
    # Pre-R-F729 these phrasings fell through to deep_research, missing
    # the 7-layer orchestrator the system prompt advertises. Each
    # requires a directional preposition (on/of/about/for) and a name
    # to follow, so generic mentions like "we did some investigation"
    # do not over-fire. Conservative additions only — entity capture
    # still gates downstream via _DD_ENTITY_CAPTURE_RE.
    r"\binvestigate\s+(?:the\s+)?counterparty\s+|"
    r"\bcounterparty\s+(?:check|diligence|review)\s+(?:on|of|for|about)\s+|"
    r"\bdeep\s+dive\s+(?:on|of|about|into)\s+|"
    r"\b(?:full\s+)?background\s+(?:on|of|about)\s+[A-Z]|"
    r"\b(?:vet|vetting)\s+(?:the\s+)?(?:counterparty|company|firm|entity)\s+|"
    # Bare "person: NAME" or "person NAME" — structured-form trigger.
    # 2026-04-11 Colin Risso incident: user typed 'person: Colin Risso /
    # Nationality: UK / Role: ...' expecting the PDD path to fire, but
    # none of the verb-form triggers matched. Also handles "individual"
    # / "subject" / "officer" / "director" as structured-form heads.
    r"\b(?:person|individual|subject|officer|director)\s*[:\-]\s*[A-Z]"
    r")",
    re.IGNORECASE,
)

# Person-DD trigger words that force type=person (alongside DD_INTENT_RE).
# No trailing \b because some branches end with [A-Z] (a letter, which is
# a word char under IGNORECASE — fails word-boundary check against the
# next letter).
_PDD_PERSON_INTENT_RE = re.compile(
    r"(?:"
    r"\bpdd\b|"
    r"\bperson\s+(?:dd|due\s+diligence)\b|"
    r"\bark[\-_]?pdd\b|"
    r"\bpep\s+(?:check|screen)\b|"
    r"\bbackground\s+(?:dd|check)\s+on\s+[A-Z]|"
    r"\bscreen\s+(?:the\s+)?(?:person|individual|director|officer|ceo|owner)\b|"
    r"\b(?:profile|dossier)\s+on\s+[A-Z]|"
    # Structured form: "person: NAME" / "individual: NAME" / etc.
    r"\b(?:person|individual|subject|officer|director)\s*[:\-]\s*[A-Z]"
    r")",
    re.IGNORECASE,
)

# Capture the entity name that follows the trigger phrase. Handles:
#   "DD on <entity>" / "PDD on <person>" / "background DD on <person>"
#   "due diligence on <entity>"
#   "PEP check on <person>"
#   "profile on <person>" / "dossier on <person>"
# 2026-04-12 New Akord Security incident: user typed "deep DD NEW AKORD
# SECURITY SRL, under the laws of Romania..." — no preposition between
# "DD" and the entity name. The capture regex required "on/for/about"
# which is natural English but not how users actually type DD requests.
# Added a branch where the preposition is optional: "DD <ENTITY_NAME>"
# directly, captured up to comma/period/newline/question mark.
_DD_ENTITY_CAPTURE_RE = re.compile(
    r"(?:"
    r"(?:full\s+|comprehensive\s+|deep\s+|ark[\-_]?)?p?dd\s+(?:report\s+)?(?:on|for|about)\s+|"
    # Preposition-less: "DD <entity>" / "deep DD <entity>" — entity
    # must start with a capital letter to disambiguate from DD followed
    # by a lowercase instruction word.
    r"(?:full\s+|comprehensive\s+|deep\s+|ark[\-_]?)?p?dd\s+(?=[A-Z])|"
    r"due\s+diligence\s+(?:report\s+)?(?:on|for|about)\s+|"
    r"ark[\-_]?(?:p)?dd\s+(?:on|for|about)\s+|"
    r"orchestrate\s+(?:p)?dd\s+(?:on|for|about)\s+|"
    r"person\s+(?:dd|due\s+diligence)\s+(?:on|for|about)\s+|"
    r"pep\s+(?:check|screen)\s+(?:on|for|about)\s+|"
    r"background\s+(?:dd|check)\s+on\s+|"
    r"(?:profile|dossier)\s+on\s+|"
    r"run\s+a?\s*(?:full\s+)?(?:background|compliance|dd|pdd)\s+(?:check|report)\s+(?:on|for|about)\s+|"
    # R-F729 (2026-05-20) — entity capture for natural-language DD
    # intents added to _DD_INTENT_RE. Each phrase must be followed by
    # an entity capture group; the head matches the trigger phrase.
    r"investigate\s+(?:the\s+)?counterparty\s+|"
    r"counterparty\s+(?:check|diligence|review)\s+(?:on|of|for|about)\s+|"
    r"deep\s+dive\s+(?:on|of|about|into)\s+|"
    r"(?:full\s+)?background\s+(?:on|of|about)\s+|"
    r"(?:vet|vetting)\s+(?:the\s+)?(?:counterparty|company|firm|entity)\s+|"
    # Structured form: capture name after "person: " / "individual: " /
    # "subject: " / "officer: " / "director: ".
    r"(?:^|[,.!?\n]\s*)(?:person|individual|subject|officer|director)\s*[:\-]\s*"
    r")"
    r"(.+?)"
    # Terminators. DO NOT include bare `/` — tonight's f3ir.com DD
    # (2026-04-17 21:30) proved it: "run DD on https://f3ir.com/"
    # captured only "https:" because the first `/` after the scheme
    # killed the match. URLs inside the entity field are a legitimate
    # pattern (DD on a website → extract domain + look up registry).
    r"(?:\s*(?:\?|\.\s|$|\n|,\s*(?:nationality|dob|role|title|position|address|registered|file\s+number|I[ČC])))",
    re.IGNORECASE,
)

# Structured-form field extractors used by _detect_dd_intent when the
# message looks like 'person: NAME / Nationality: X / Role: Y'.
_STRUCTURED_FIELD_RE = re.compile(
    r"\b(?:nationality|nat|citizen(?:ship)?|dob|date\s+of\s+birth|born|"
    r"role|title|position|organisation|organization|employer|company|"
    r"firm|at)\s*[:\-]\s*([^/\n,?]+?)\s*(?=/|\n|$|,\s*(?:nationality|nat|"
    r"citizen|dob|date\s+of\s+birth|born|role|title|position|"
    r"organisation|employer|company|at)\b)",
    re.IGNORECASE,
)


