            _r473_record_read_doc(
                _r473_time.monotonic() - _r473_t0, filename, len(raw_bytes), "unknown",
            )
            return {
                "ok": False,
                "error": "unrecognised file format (magic-byte check failed)",
                "filename": filename,
                "claimed_mime": mimetype,
                "byte_length": len(raw_bytes),
            }
