@router.post("/admin/purge-gaps")
@fail_wire(module="aria", gap_type="engine_failure")
async def purge_gaps_ep(request: Request):
    """Purge stale capability gaps from the proactive gap tracker.

    Removes gaps older than max_age_days (default 7). Gaps accumulate
    when users ask about topics ARIA can't answer — stale ones from
    resolved areas hide ARIA's actual capabilities.

    Body (optional):
        {"max_age_days": 3, "dry_run": true}
    """
    body = {}
    try:
        body = await request.json()
    except Exception:
        pass
    max_age = int(body.get("max_age_days", 7))
    dry_run = bool(body.get("dry_run", False))

    from ..intel import redis_store as rs
    import time
    GAP_KEY = "crucix:aria:proactive:gap_tracker"
    gaps = await rs.get_json(GAP_KEY) or {}
    now = time.time()
    cutoff = now - (max_age * 86400)

    stale = {k: v for k, v in gaps.items() if v.get("last_seen", 0) < cutoff}
    fresh = {k: v for k, v in gaps.items() if v.get("last_seen", 0) >= cutoff}

    if not dry_run and stale:
        await rs.set_json(GAP_KEY, fresh, ex=14 * 86400)

    return {
        "total": len(gaps),
        "stale": len(stale),
        "removed": len(stale) if not dry_run else 0,
        "remaining": len(fresh),
        "dry_run": dry_run,
        "max_age_days": max_age,
        "stale_topics": list(stale.keys())[:20],
    }


# ─────────────────────────────────────────────────────────────────────────
# R-F261 (2026-05-11) — Upstash → SQLite state migration via HTTP.
#
# Operator was unable to run `fly ssh console` from Windows (Kaspersky deleted
# the upgraded flyctl binary). This endpoint lets the operator trigger the
# migration script from any machine with curl + the bearer token. Runs
# in-process inside the fly.io machine, so REDIS_URL and /data are both in
# scope. Auth-gated via the existing require_aria_token dependency (default
# auth path for /api/aria/admin/*).
# ─────────────────────────────────────────────────────────────────────────

# Single-flight guard for /admin/migrate-state. R-F261 pass-1 verification
# flagged that two simultaneous operator-triggered migrations could race on
# state_store.close(). Lazy-init lock (same pattern as state_store.R-F256)
# so the module imports cleanly without a running loop. A second concurrent
# call returns 409 Conflict; the first runs to completion uninterrupted.
_migration_lock: "Optional[asyncio.Lock]" = None


def _get_migration_lock() -> asyncio.Lock:
    global _migration_lock
    if _migration_lock is None:
        import asyncio as _aio_m
        _migration_lock = _aio_m.Lock()
    return _migration_lock


@router.post("/admin/migrate-state")
@fail_wire(module="aria", gap_type="engine_failure")
async def admin_migrate_state_ep(request: Request):
    """Migrate every key from Upstash Redis to the SQLite state_store.

    Body (all optional):
        {
            "dry_run": true,           # default false; true = scan + count, no writes
            "prefix": ["crucix:..."],  # optional list of prefixes to scope migration
            "limit":  0                # default 0 = no cap; 1000 = stop after 1000 keys
        }

    Returns the migration manifest (counts by type, sample, errors,
    duration_s). Same shape as the CLI script's stdout output, so the
    operator gets identical observability whether invoked locally or
    over HTTP.

    Hot path: imports `scripts.migrate_state._migrate` and runs it inline.
    Single-flight via module-level asyncio.Lock — a second concurrent call
    returns 409 Conflict so the first run isn't interrupted mid-close().
    Re-running after completion writes the same keys (last-write-wins on
    the SQLite UPSERT) which is idempotent and harmless.
    """
    # Single-flight guard — second concurrent call returns 409 (don't race).
    lock = _get_migration_lock()
    if lock.locked():
        raise HTTPException(
            status_code=409,
            detail="state migration already in progress; retry once it completes",
        )

    body: dict = {}
    try:
        body = await request.json()
    except Exception:
        pass

    dry_run = bool(body.get("dry_run", False))
    prefixes = body.get("prefix") or []
    if not isinstance(prefixes, list):
        prefixes = [str(prefixes)]
    prefixes = [str(p) for p in prefixes if p]
    try:
        limit = int(body.get("limit", 0))
    except (TypeError, ValueError):
        limit = 0

    # Import the migration entrypoint. The script lives under repo
    # `scripts/`, which is on PYTHONPATH in the fly.io container per the
    # Dockerfile's WORKDIR=/app + COPY scripts ./scripts.
    try:
        import sys as _sys
        import pathlib as _pathlib
        _repo_root = _pathlib.Path(__file__).resolve().parents[2]
        _scripts_dir = _repo_root / "scripts"
        if str(_scripts_dir) not in _sys.path:
            _sys.path.insert(0, str(_scripts_dir))
        from migrate_state import _migrate as _do_migrate
    except Exception as e:
        raise HTTPException(
            status_code=500,
            detail=f"migrate_state import failed: {e!s}",
        )

    async with lock:
        try:
            result = await _do_migrate(prefixes, dry_run, limit)
        except SystemExit as e:
            # _migrate raises SystemExit("REDIS_URL not set...") for missing config
            raise HTTPException(status_code=400, detail=str(e))
        except Exception as e:
            raise HTTPException(
                status_code=500,
                detail=f"migration failed: {e!s}",
            )

    return {"ok": True, **result}


# R-F388 (2026-05-12) — WhatsApp listener auth-bundle backup, routed
# through fly.io's SQLite state_store. Closes the last Upstash-dependent
# surface on seenode: the WA listener was using Upstash as durable
# cross-deploy storage for its Baileys auth files (creds.json + app-state-*
# + pre-key-* + session-*). When Seenode redeploys wipe the local
# `./wa-listener-auth/` directory, restoring from Upstash was the only path
# back to a connected session without a QR re-scan.
#
# This pair of endpoints puts the same bundle in fly.io's SQLite (R-F261),
# which is operator-owned infrastructure with persistent volume + bearer
# auth. The seenode client (lib/whatsapp/waListener.mjs) calls these via
# the existing ARIA_BRAIN_URL + ARIA_INTERNAL_TOKEN.
#
# Bundle size cap matches the seenode-side guard: 500 KB total. Anything
# larger means the WA session has drifted (corrupt / very busy session
# history) and a fresh scan is healthier than keeping a bloated blob.
# R-F683 (2026-05-18) — wa-auth/backup idempotency / storm debounce.
# Live fly logs 2026-05-18 09:51:46-09:52:02 + 2026-05-18 07:51:46-07:52:02
# both showed 31+ POSTs from the seenode WA listener inside ~18 seconds.
# Root cause is on the seenode side: `backupAuthToRedis` is called from
# every Baileys `creds.update` event (key rotation, message send, app-state
# sync) with no client-side debounce. We can't change the seenode caller
# from here, but we CAN bound the damage server-side: hash the bundle on
# arrival and short-circuit if the same bundle was just written.
_WA_BACKUP_DEBOUNCE_SEC = 5.0
_WA_LAST_BACKUP: dict = {"hash": None, "at": 0.0, "result": None}


@router.post("/wa-auth/backup")
@fail_wire(module="aria", gap_type="engine_failure")
async def wa_auth_backup_ep(request: Request):
    """Persist the WhatsApp Baileys auth bundle.

    Body:
        {"files": {"creds.json": "...", "app-state-...": "...", ...}}

    Response: {"ok": true, "files": N, "bytes": M, "debounced": bool}

    The bundle is stored under SQLite key ``wa_listener:auth_bundle`` and
    survives fly.io restarts via the /data volume. No TTL — auth bundles
    are only invalidated by an explicit DELETE (operator action) or a
    fresh backup overwriting the slot.

    R-F683 idempotency: if the incoming bundle's content-hash matches the
    previous backup AND the previous backup landed within
    _WA_BACKUP_DEBOUNCE_SEC, we return the cached success without writing
    to SQLite. The response shape stays the same with an additional
    ``debounced: true`` field so the caller can tell. This bounds the
    damage from the seenode storm (no SQLite write churn, no /data IO).
    """
    try:
        body = await request.json()
    except Exception:
        raise HTTPException(status_code=400, detail="invalid JSON body")

    files = body.get("files") if isinstance(body, dict) else None
    if not isinstance(files, dict) or not files:
        raise HTTPException(status_code=400, detail="body.files must be a non-empty object")

    total_bytes = 0
    for name, content in files.items():
        if not isinstance(name, str) or not isinstance(content, str):
            raise HTTPException(status_code=400, detail="every entry must be {string: string}")
        total_bytes += len(content)

    # Hard cap is 2× the seenode pre-upload guard (500 KB) for headroom.
    # Above 1 MB the WA session has drifted (corrupt or excessive history);
    # a fresh QR scan is healthier than storing a bloated blob.
    MAX_BUNDLE_BYTES = 1_000_000
    if total_bytes > MAX_BUNDLE_BYTES:
        raise HTTPException(
            status_code=413,
            detail=f"bundle {total_bytes} bytes exceeds {MAX_BUNDLE_BYTES} cap",
        )

    # R-F683 — content-hash the bundle for idempotency. sort_keys ensures
    # the same files dict in any order hashes the same. Stable separators
    # avoid whitespace-only differences. SHA-256 is fast (~5µs for 500KB).
    import hashlib as _hashlib
    bundle_serial = json.dumps(files, sort_keys=True, separators=(",", ":"))
    bundle_hash = _hashlib.sha256(bundle_serial.encode("utf-8")).hexdigest()
    now_ts = time.time()
    if (
        _WA_LAST_BACKUP["hash"] == bundle_hash
        and (now_ts - _WA_LAST_BACKUP["at"]) < _WA_BACKUP_DEBOUNCE_SEC
        and _WA_LAST_BACKUP["result"] is not None
    ):
        # Same bundle, very recent — short-circuit. SQLite is untouched.
        return {**_WA_LAST_BACKUP["result"], "debounced": True}

    from aria_service.intel import state_store

    bundle = {
        "files": files,
        "updated_at": datetime.now(timezone.utc).isoformat(),
        "files_count": len(files),
        "bytes": total_bytes,
    }
    await state_store.set_json("wa_listener:auth_bundle", bundle)
    result = {"ok": True, "files": len(files), "bytes": total_bytes}
    _WA_LAST_BACKUP["hash"] = bundle_hash
    _WA_LAST_BACKUP["at"] = now_ts
    _WA_LAST_BACKUP["result"] = result
    return {**result, "debounced": False}


@router.get("/wa-auth/restore")
@fail_wire(module="aria", gap_type="engine_failure")
async def wa_auth_restore_ep():
    """Retrieve the WhatsApp Baileys auth bundle for restore on cold boot.

    Returns ``{"ok": True, "files": {…}}`` when present, or
    ``{"ok": False, "reason": "missing"}`` when no bundle has been written
    yet. The 200 status is intentional in both cases — the seenode client
    distinguishes by inspecting ``ok``.
    """
    from aria_service.intel import state_store

    bundle = await state_store.get_json("wa_listener:auth_bundle")
    if not bundle or not isinstance(bundle, dict) or "files" not in bundle:
        return {"ok": False, "reason": "missing"}
    return {
        "ok": True,
        "files": bundle.get("files") or {},
        "updated_at": bundle.get("updated_at"),
        "files_count": bundle.get("files_count"),
        "bytes": bundle.get("bytes"),
    }


