# GET /api/aria/vision-status — Diagnostic for image OCR configuration
@router.get("/vision-status")
@fail_wire(module="aria", gap_type="engine_failure")
async def vision_status_ep(request: Request):
    """Report whether ARIA can do image OCR right now and which backend will run.

    ARIA's image OCR is LOCAL-FIRST. She tries (in order):
        1. EasyOCR  (pure Python, no system binary, recommended for independence)
        2. Tesseract (needs Tesseract binary + pytesseract)
        3. Ollama vision model (auto-detected if running locally with llava/minicpm-v/etc)
        4. Cloud LLM vision (only if ARIA_VISION_PROVIDER + key are explicitly set)

    She is independent of any cloud LLM for image reading by default.
    """
    # ── Probe local backends ─────────────────────────────────────────────
    easyocr_available = False
    try:
        import easyocr  # noqa: F401
        easyocr_available = True
    except ImportError:
        pass

    tesseract_available = False
    try:
        import pytesseract  # noqa: F401
        from PIL import Image  # noqa: F401
        tesseract_available = True
    except ImportError:
        pass

    ollama_vision_model = await aria_ocr._detect_ollama_vision_model()

    # ── Probe optional cloud backend ─────────────────────────────────────
    cfg = aria_ocr.get_vision_config()
    llm = get_llm(request)
    fallback_inner = aria_ocr._unwrap_provider(llm) if llm else None
    fallback_provider_name = (getattr(fallback_inner, "name", "") or "").lower() if fallback_inner else None
    fallback_has_key = bool(getattr(fallback_inner, "_api_key", "")) if fallback_inner else False

    # Auto-install state
    install_status = aria_ocr.get_auto_install_status()

    # Determine which backend will actually run for the next image. OCR.space
    # is the always-on free public fallback so the chain ALWAYS has at least
    # one usable backend — there's no "none" state any more by default.
    if easyocr_available:
        active = "easyocr"
    elif tesseract_available:
        active = "tesseract"
    elif ollama_vision_model:
        active = f"ollama:{ollama_vision_model}"
    elif cfg["dedicated_provider_configured"]:
        active = f"cloud:{cfg['dedicated_provider']}"
    elif fallback_inner is not None and fallback_has_key:
        active = f"cloud:{fallback_provider_name}"
    else:
        # Free public fallback — always available, no setup
        active = "ocrspace_free"

    is_working = True  # OCR.space is always reachable as last resort

    # Setup hints — lead with the local options to nudge toward independence
    setup_instructions = []
    if active in ("ocrspace_free",):
        if install_status.get("started"):
            setup_instructions.append(
                "Auto-install of easyocr is RUNNING in the background — "
                "the next image will be served fully locally."
            )
        else:
            setup_instructions.append(
                "Currently using free public OCR fallback. For full independence, "
                "install local OCR: `pip install easyocr Pillow pytesseract` "
                "(or set ARIA_OCR_AUTO_INSTALL=1 to auto-install on next image)."
            )
    elif active == "tesseract" and not easyocr_available:
        setup_instructions.append(
            "Tip: `pip install easyocr` for higher-quality local OCR"
        )

    return {
        "ok": is_working,
        "independent": active in ("easyocr", "tesseract") or active.startswith("ollama:"),
        "active_backend": active,
        "auto_install": install_status,
        "local_backends": {
            "easyocr": easyocr_available,
            "tesseract": tesseract_available,
            "ollama_vision_model": ollama_vision_model,
        },
        "free_public_fallback": {
            "name": "OCR.space",
            "always_available": True,
            "max_image_size_mb": 1,
            "monthly_quota": "25,000 per IP",
        },
        "cloud_backend": {
            "dedicated_provider": cfg["dedicated_provider"],
            "dedicated_configured": cfg["dedicated_provider_configured"],
            "fallback_provider": fallback_provider_name,
            "fallback_available": fallback_inner is not None and fallback_has_key,
        },
        "main_llm": getattr(llm, "name", "?") if llm else None,
        "setup_instructions": setup_instructions,
        "philosophy": (
            "ARIA reads images out of the box via free public fallback, "
            "and auto-installs local OCR in the background so subsequent "
            "images become fully offline + independent."
        ),
    }


# 46. POST /api/aria/ocr — Extract text from image
# R-F1311: supports async mode (async=true) for the WA listener image path.
# In async mode, enqueues a background OCR job and returns a job_id immediately.
# The caller polls /api/aria/ocr/result/{job_id} until status='done'.
# Sync mode (default) returns the result inline as before.

# R-F2089 (Tier 2) — OCR job store moved from an in-process dict to redis_store,
# mirroring _readdoc_job_set/_chat_job_set. With multiple web workers (Tier 3) a
# job created on worker A must be pollable on worker B; an in-memory dict gave
# "job not found" across workers. TTL matches the readdoc poll window.
_OCR_JOB_PREFIX = "crucix:aria:ocr_job:"
_OCR_JOB_TTL_S = 3600  # 1h — long enough for a WA/web poll window + retries

async def _ocr_job_set(job_id: str, data: dict) -> bool:
    """Store an OCR job. Returns True on success, False on store failure (so a
    caller can answer 503 instead of falsely 202, per the _readdoc_job_set class)."""
    try:
        from ..intel import redis_store as _rs_ocr
        import time as _t_ocr
        await _rs_ocr.set_json(_OCR_JOB_PREFIX + job_id, {**data, "ts": _t_ocr.time()},
                               ex=_OCR_JOB_TTL_S)
        return True
    except Exception as e:
        _log.warning("R-F2089 ocr job-store set failed for %s: %s", job_id, e)
        return False

async def _ocr_job_get(job_id: str) -> Optional[dict]:
    from ..intel import redis_store as _rs_ocr
    try:
        return await _rs_ocr.get_json(_OCR_JOB_PREFIX + job_id)
    except Exception as e:
        _log.warning("R-F2089 ocr job-store read failed for %s: %s", job_id, e)
        return None


@router.post("/ocr")
@fail_wire(module="aria", gap_type="engine_failure")
async def ocr_ep(request: Request):
    body = await request.json()
    image_b64 = body.get("image", "")
    filename = body.get("filename", "image.jpg")
    context = body.get("context", "")
    if not image_b64:
        raise HTTPException(status_code=400, detail="image (base64) required")
    import base64
    try:
        image_data = base64.b64decode(image_b64)
    except Exception:
        raise HTTPException(status_code=400, detail="Invalid base64 image data")

    _log.info("OCR request: filename=%s size=%d bytes context=%s",
              filename, len(image_data), context[:120])

    # R-F1311: async mode — enqueue background job, return job_id immediately
    if body.get("async"):
        import uuid as _uuid_ocr
        _job_id = _uuid_ocr.uuid4().hex[:12]
        # R-F1865 (audit DD-07): stamp the JWT-pinned owner into the job dict
        # so GET /ocr/result/{id} can enforce ownership (the extracted text is
        # confidential). Node pins body.user_id from the JWT.
        _ocr_owner = (body.get("user_id") or "").strip()
        await _ocr_job_set(_job_id, {"status": "processing", "filename": filename, "user_id": _ocr_owner})

        async def _ocr_async_run():
            try:
                llm = get_llm(request)
                _res = await aria_ocr.extract_text_from_image(image_data, filename, context, llm)
                await _ocr_job_set(_job_id, {"status": "done", "result": _res, "filename": filename, "user_id": _ocr_owner})
            except Exception as _e:
                _log.warning("R-F1311 async OCR job %s failed: %s", _job_id, _e)
                await _ocr_job_set(_job_id, {"status": "failed", "error": str(_e)[:300], "filename": filename, "user_id": _ocr_owner})

        # R-F1377 — strong ref: a GC'd OCR job = scanned-document parse that
        # never finishes (polled store stuck at "processing").
        _hold_job_task(asyncio.create_task(_ocr_async_run(), name=f"ocrjob.{_job_id}"))
        return {
            "async": True, "job_id": _job_id, "status": "processing",
            "poll_url": f"/api/aria/ocr/result/{_job_id}",
            "message": "OCR started — poll the result URL.",
        }

    # Sync mode (default)
    llm = get_llm(request)
    result = await aria_ocr.extract_text_from_image(image_data, filename, context, llm)

    # Always log the outcome so we can debug "silent failures" from the logs
    if result.get("text"):
        _log.info("OCR success: method=%s chars=%d filename=%s",
                  result.get("method"), len(result["text"]), filename)
    else:
        _log.warning("OCR returned empty result for %s (size=%d). Method last tried: %s. "
                     "Backends tried: %s. Note: %s",
                     filename, len(image_data), result.get("method"),
                     result.get("tried"), result.get("note"))
    return result


@router.get("/ocr/result/{job_id}")
@fail_wire(module="aria", gap_type="engine_failure")
async def ocr_result_ep(job_id: str, user_id: str = ""):
    """GET /api/aria/ocr/result/{job_id} — poll OCR job status.
    R-F1311: mirrors /read-document/result/{job_id} for the async OCR path.
    R-F1865 (audit DD-07): `user_id` (Node pins it from the JWT) enforces
    ownership — the extracted document text is confidential. not_found on
    mismatch leaks nothing. Legacy jobs (no user_id) + admin callers
    (user_id='') still resolve, exactly like read-document."""
    job = await _ocr_job_get(job_id)
    if not job:
        return {"status": "not_found", "job_id": job_id}
    _owner = (job.get("user_id") or "").strip()
    if user_id and _owner and _owner != user_id:
        return {"status": "not_found", "job_id": job_id}
    if job["status"] == "done":
        return {"status": "done", "result": job.get("result"), "job_id": job_id}
    if job["status"] == "failed":
        return {"status": "failed", "error": job.get("error", "unknown"), "job_id": job_id}
    return {"status": "processing", "job_id": job_id}


