class ClassifyRequest(BaseModel):
    description: str

@router.post("/compliance/classify")
@fail_wire(module="aria", gap_type="engine_failure")
async def compliance_classify_ep(req: ClassifyRequest):
    """Classify a product description against UK Military List categories."""
    desc = (req.description or "").strip()
    if not desc or len(desc) < 3:
        raise HTTPException(status_code=400, detail="description required (min 3 chars)")

    ML_KEYWORDS: dict[str, tuple[str, list[str]]] = {
        "ML1":  ("Smooth-bore weapons (small arms)",        ["small arms", "rifle", "pistol", "machine gun", "firearm", "carbine", "shotgun"]),
        "ML2":  ("Smooth-bore weapons of calibre 20mm+",    ["mortar", "cannon", "howitzer", "artillery", "field gun"]),
        "ML3":  ("Ammunition and fuze setting",             ["ammunition", "cartridge", "round", "bullet", "fuze", "shell"]),
        "ML4":  ("Bombs, torpedoes, rockets, missiles",     ["missile", "rocket", "torpedo", "bomb", "mine", "warhead", "atgm", "manpads"]),
        "ML5":  ("Fire control, surveillance",              ["fire control", "targeting", "laser designator", "rangefinder"]),
        "ML6":  ("Ground vehicles & components",            ["armoured vehicle", "armored vehicle", "apc", "ifv", "tank", "mrap", "humvee"]),
        "ML7":  ("CBRN agents",                             ["chemical", "biological", "toxin", "nerve agent", "riot control"]),
        "ML8":  ("Energetic materials",                     ["explosive", "propellant", "detonator", "rdx", "tnt", "c4"]),
        "ML9":  ("Vessels of war",                          ["vessel", "warship", "patrol boat", "naval", "submarine", "frigate", "corvette"]),
        "ML10": ("Aircraft & components",                   ["aircraft", "helicopter", "uav", "drone", "fighter", "bomber", "rotorcraft"]),
        "ML11": ("Electronic equipment",                    ["communication", "radio", "crypto", "c4isr", "command and control", "jammer"]),
        "ML13": ("Body armour & protective gear",           ["armour", "armor", "body armour", "helmet", "ballistic vest", "protective"]),
        "ML15": ("Imaging & countermeasure equipment",      ["radar", "sensor", "electro-optical", "infrared", "thermal", "lidar", "night vision"]),
        "ML22": ("Training & advisory",                     ["training", "simulation", "advisory", "instructor"]),
    }

    lower = desc.lower()
    classifications = []
    for code, (label, kws) in ML_KEYWORDS.items():
        for kw in kws:
            if kw in lower:
                classifications.append({
                    "code": code,
                    "category": label,
                    "description": label,
                    "controlled": True,
                    "matched_keyword": kw,
                    "confidence": 0.85 if len(kw) > 6 else 0.70,
                })
                break

    if not classifications:
        classifications.append({
            "code": "UNCLASSIFIED",
            "category": "No obvious ML category",
            "description": "Item does not match any known UK Military List keywords. Manual review required.",
            "controlled": False,
            "confidence": 0.30,
        })

    return {
        "input": desc,
        "classifications": classifications,
        "result": classifications[0]["code"],
        "category": classifications[0]["category"],
        "disclaimer": "Keyword classification only — formal export control assessment required.",
    }


class SanctionsRequest(BaseModel):
    name: str

@router.post("/compliance/sanctions")
@fail_wire(module="aria", gap_type="engine_failure")
async def compliance_sanctions_ep(req: SanctionsRequest, request: Request):
    """Sanctions check — proxies to Node entityMatcher and falls back to knowledge base."""
    name = (req.name or "").strip()
    if not name or len(name) < 2:
        raise HTTPException(status_code=400, detail="name required (min 2 chars)")

    matches: list[dict] = []
    error = None
    screened = False   # R-F2569: did the authoritative sanctions screen ACTUALLY run?
    try:
        # R-F2571: screen in-process via the canonical never-false-clean check_sanctions
        # (same authoritative path DD reports use) instead of the broken cross-tier Node hop.
        from ..intel.sanctions_canonical.lookup import check_sanctions as _check_sanctions
        _cs = await asyncio.to_thread(_check_sanctions, name)
        _verdict = _cs.get("verdict")
        if _verdict == "INSUFFICIENT_DATA" or _cs.get("source_unavailable"):
            error = _cs.get("reason") or "sanctions_store_unavailable"
        else:
            screened = True
            for m in (_cs.get("matches") or []):
                matches.append({
                    "name": m.get("formatted_name") or m.get("name") or name,
                    "list": m.get("source") or "Sanctions list",
                    "score": m.get("match_score"),
                    "reason": f"canonical sanctions verdict: {_verdict}",
                })
    except Exception as e:
        error = str(e)
        _log.warning("Sanctions check upstream failed: %s", e)

    # Knowledge-base fallback — search for the entity in stored intel
    kb_hits = knowledge.search_knowledge(name) or ""
    kb_flagged = bool(kb_hits and re.search(r"sanction|embargo|ofac|ofsi|debarred", kb_hits, re.IGNORECASE))
    if kb_flagged:
        matches.append({
            "name": name,
            "list": "ARIA knowledge base",
            "score": 0.6,
            "reason": "Mentioned alongside sanctions/embargo terms in stored intelligence",
        })

    return {
        "name": name,
        "matches": matches,
        "results": matches,
        "match_count": len(matches),
        # R-F2569 — NEVER-FALSE-CLEAN: "clear" only when the authoritative screen actually
        # RAN and returned no matches. A failed/unavailable screen (error set) is NOT clear
        # — the KB fallback is supplementary, not authoritative (was: clear=True whenever
        # matches was empty, even when the backend errored → false clean on unscreened entity).
        "clear": len(matches) == 0 and screened,
        "screened": screened,
        "screening_unavailable": (not screened),
        "error": error,
        "disclaimer": "Pre-screen only. Verify against authoritative lists (OFAC, OFSI, EU, UN) before any commercial action.",
    }


class RiskRequest(BaseModel):
    country: str

@router.post("/compliance/risk")
@fail_wire(module="aria", gap_type="engine_failure")
async def compliance_risk_ep(req: RiskRequest):
    """Country risk assessment — sanctions regimes, embargoes, ML risk tier."""
    country_input = (req.country or "").strip()
    if not country_input or len(country_input) < 2:
        raise HTTPException(status_code=400, detail="country required (min 2 chars)")

    # Country name → ISO2 (best-effort)
    NAME_TO_ISO = {
        "russia": "RU", "belarus": "BY", "iran": "IR", "north korea": "KP", "syria": "SY",
        "cuba": "CU", "venezuela": "VE", "central african republic": "CF", "car": "CF",
        "drc": "CD", "congo": "CD", "eritrea": "ER", "iraq": "IQ", "libya": "LY",
        "mali": "ML", "somalia": "SO", "south sudan": "SS", "sudan": "SD", "yemen": "YE",
        "afghanistan": "AF", "haiti": "HT", "myanmar": "MM", "burma": "MM", "nicaragua": "NI",
        "zimbabwe": "ZW", "china": "CN",
        "guinea-bissau": "GW", "guinea bissau": "GW", "cameroon": "CM", "niger": "NE",
        "burkina faso": "BF", "chad": "TD", "pakistan": "PK", "egypt": "EG", "turkey": "TR",
        "india": "IN", "ethiopia": "ET",
        "angola": "AO", "mozambique": "MZ", "nigeria": "NG", "senegal": "SN", "ivory coast": "CI",
        "côte d'ivoire": "CI", "uganda": "UG", "indonesia": "ID", "vietnam": "VN", "colombia": "CO",
        "peru": "PE", "saudi arabia": "SA", "uae": "AE", "united arab emirates": "AE", "jordan": "JO",
    }
    # ── R-F3572 — AN ISO CODE IS NOT A NAME PREFIX ──────────────────────────
    #
    # This was:
    #     iso = ... else NAME_TO_ISO.get(name, country_input.upper()[:2])
    # so any country missing from the hand-map got the FIRST TWO LETTERS OF ITS
    # NAME as its ISO code, and those collide with real codes belonging to other
    # countries. Measured: "Nepal" -> "NE", which is NIGER, which is in
    # HIGH_RISK — so Nepal was reported HIGH RISK by name, carrying another
    # country's verdict. Also "Chile" -> "CH" (Switzerland), "Sweden" -> "SW",
    # "Portugal" -> "PO", each then classified on a code that is not theirs.
    #
    # Resolution order, and NO fallback: the endpoint's own curated map, then the
    # canonical country_taxonomy resolver. If neither knows the country, the ISO
    # is UNRESOLVED and set-membership must not be consulted at all — a guessed
    # code produces a confident verdict about the wrong country, which is worse
    # than no verdict.
    if len(country_input) == 2 and country_input.isalpha():
        iso = country_input.upper()
    else:
        iso = NAME_TO_ISO.get(country_input.lower())
        if not iso:
            try:
                from ..intel import country_taxonomy as _ct
                iso = _ct.to_iso2(country_input)
            except Exception:
                _log.debug("[compliance/risk] iso resolution failed", exc_info=True)
                iso = None
    # Sentinel that can never match a real ISO2, so the set lookups below are
    # simply all-miss rather than needing a guard at each one.
    iso = iso or "??"

    EMBARGOED = {"RU","BY","IR","KP","SY","CU","VE","CF","CD","ER","IQ","LY","ML","SO","SS","SD","YE","AF","HT","MM","NI","ZW","CN"}
    HIGH_RISK = {"GW","CM","NE","BF","TD","PK","EG","TR","IN","ET"}
    MEDIUM_RISK = {"AO","MZ","NG","SN","CI","UG","ID","VN","CO","PE","SA","AE","JO"}

    if iso in EMBARGOED:
        level, score = "HIGH", 90
        regimes = ["UN SC", "EU restrictive measures", "UK OFSI"]
        notes = f"{country_input} is subject to international arms embargo. Most defence exports prohibited or require explicit Government licence."
    elif iso in HIGH_RISK:
        level, score = "HIGH", 70
        regimes = ["Enhanced due diligence required"]
        notes = f"{country_input} is high-risk. End-user verification, diversion risk assessment, and SITCL likely required."
    elif iso in MEDIUM_RISK:
        level, score = "MEDIUM", 45
        regimes = ["Standard licensing"]
        notes = f"{country_input} permits standard defence exports but requires SITCL with end-use certificate."
    else:
        # ── R-F3572 — AN UNLISTED COUNTRY IS UNASSESSED, NOT LOW-RISK ────────
        #
        # This branch returned level="LOW", score=20 and the sentence
        # "{country} is a low-risk destination. Standard export controls apply."
        # for EVERY country absent from the three hardcoded sets above — which is
        # most of the world. That is an assertion the endpoint has no basis for:
        # the sets are a partial hand-list, so "not in the list" means NOT
        # CHECKED, and it was being rendered as CHECKED AND CLEAR.
        #
        # It is user-facing. aria_wa_listener.mjs:1815 puts this straight into a
        # WhatsApp reply as "🟢 Risk level: LOW", so a defence operator asking
        # about an uncovered destination was told it was low-risk by name.
        # That is the false-clean shape the sanctions work exists to prevent.
        #
        # UNKNOWN is not a new contract: aria_wa_listener.mjs:1816 already reads
        # `d.risk_level || d.level || 'UNKNOWN'`, its emoji map already falls
        # through to ⚪, and server.mjs:3713 emits `risk_level: 'UNKNOWN'` in its
        # own offline fallback. Every consumer was built for it; this endpoint
        # simply never sent it.
        level, score = "UNKNOWN", None
        regimes = []
        notes = (
            f"{country_input} is not covered by ARIA's curated country-sanctions "
            f"set or its embargo/high-risk lists, so NO risk determination has "
            f"been made. This is an absence of assessment, not a clean result — "
            f"check OFSI, the EU consolidated list, UN Security Council measures "
            f"and the ECJU rating directly before acting."
        )

    # ── R-F3572 — use the CURATED regimes when we actually hold them ─────────
    #
    # intel/country_sanctions.py holds 25 SanctionsRegime records across 11
    # countries with the real instruments, regime types, exceptions and source
    # citations, and its docstring calls format_regime_answer "the PRIMARY answer
    # for 'is [country] under sanctions?' questions". NOTHING CALLED IT — verified
    # repo-wide, the module was referenced only by its own tests, a gap_type
    # registry entry and a comment. Meanwhile this endpoint, the live one, served
    # the generic strings ["UN SC", "EU restrictive measures", "UK OFSI"].
    #
    # So the answer is upgraded where the curated data exists, and the hardcoded
    # sets stay as the floor for the countries it does not cover yet. Additive
    # only: every existing field keeps its meaning and type.
    regime_detail: list[dict] = []
    try:
        from ..intel import country_sanctions as _cs
        _curated = _cs.format_regime_answer(country_input)
    except Exception:
        _log.debug("[compliance/risk] curated sanctions lookup failed", exc_info=True)
        _curated = None

    if _curated and _curated.get("found"):
        regime_detail = _curated.get("regimes") or []
        # Real instrument citations replace the generic labels.
        regimes = [
            f"{(r.get('source') or '').upper()}: {r.get('regime_type', '').replace('_', ' ')}"
            for r in regime_detail
        ] or regimes
        # A curated comprehensive regime or arms embargo outranks the hand-list.
        if _curated.get("has_comprehensive") or _curated.get("has_arms_embargo"):
            level, score = "HIGH", max(score or 0, 90)
        elif _curated.get("has_targeted") and level == "UNKNOWN":
            level, score = "MEDIUM", 55
        notes = _curated.get("summary") or notes

    return {
        "country": country_input,
        "iso": iso,
        "risk_level": level,
        "level": level,
        "score": score,
        "sanctions_regimes": regimes,
        # R-F3572 — the curated per-regime records (instruments, exceptions,
        # citations). Empty when ARIA holds no curated entry for the country,
        # which is itself the honest signal that the answer is list-based.
        "regime_detail": regime_detail,
        "assessed": level != "UNKNOWN",
        "embargoes": ["UN/EU/UK arms embargo"] if iso in EMBARGOED else [],
        # R-F3572 — "LOW" is no longer reachable and that is the point: the three
        # sets above enumerate RISK, never safety, so nothing in this endpoint can
        # establish that a country IS low-risk. The branch is kept because the
        # field is part of a contract WhatsApp and the web tier both render, and
        # a curated low-risk source would legitimately restore it.
        "export_controls": (
            "SITCL + end-user certificate" if level in ("HIGH", "MEDIUM")
            else "Unknown — country not assessed" if level == "UNKNOWN"
            else "Standard SITCL"
        ),
        "notes": notes,
        "disclaimer": "Advisory only. Confirm with current Foreign Office guidance and ECJU rating before action.",
    }


