# ── Entity Graph ──────────────────────────────────────────────────────────

@router.get("/entity-graph/{run_id}")
@fail_wire(module="aria", gap_type="engine_failure")
async def entity_graph_ep(run_id: str, user_id: str = ""):
    """Load a previously saved entity relationship graph from a DD run.
    R-F1852 (audit, DD stage 4) — `user_id` (Node pins it from the JWT) enforces
    ownership; the graph is DD-derived and confidential to the run's owner."""
    from ..intel import entity_graph
    graph = await entity_graph.ERGraph.load(run_id)
    if not graph:
        raise HTTPException(status_code=404, detail=f"No entity graph for run_id {run_id}")
    # R-F1852: the entity-graph store carries no owner, but it shares run_id with the
    # DD report (which DOES store the owner — R-F1820). Authorize via that report.
    # 404 on mismatch to avoid leaking existence. user_id='' = admin/no-filter path.
    if user_id:
        try:
            from ..intel import dd_orchestrator as _ddo852
            _rep852 = await _ddo852.get_report(run_id)
            _owner852 = (_rep852.get("user_id") or "").strip() if _rep852 else ""
            if _owner852 and _owner852 != user_id:
                raise HTTPException(status_code=404, detail=f"No entity graph for run_id {run_id}")
        except HTTPException:
            raise
        except Exception as _eg_owner_e:
            # R-F1886 (review): FAIL CLOSED. The old `except: pass` swallowed any
            # error loading the owning DD report and then RETURNED the confidential
            # graph — a store blip became an IDOR bypass. If ownership cannot be
            # verified for a user-scoped caller, DENY (404).
            _log.warning("entity_graph ownership check errored for %s — denying (fail-closed): %s",
                         run_id, _eg_owner_e)
            raise HTTPException(status_code=404, detail=f"No entity graph for run_id {run_id}")
    return {
        "run_id": run_id,
        "nodes": len(graph.nodes),
        "edges": len(graph.edges),
        "summary": graph.get_network_summary(),
        "graph": {
            "nodes": [{
                "id": n.entity_id, "type": n.entity_type, "label": n.label,
                "jurisdiction": n.jurisdiction, "risk_level": n.risk_level,
                "risk_reason": n.risk_reason,
            } for n in graph.nodes.values()],
            "edges": [{
                "from": e.from_id, "to": e.to_id, "type": e.relationship_type,
                "source": e.source,
            } for e in graph.edges],
        },
    }


# ── Fuzzy sanctions screening (OpenSanctions + Levenshtein + Metaphone) ─────

class FuzzyScreenRequest(BaseModel):
    name: str
    aliases: list[str] | None = None
    threshold: float = 0.78

@router.post("/sanctions/fuzzy")
@fail_wire(module="aria", gap_type="engine_failure")
async def sanctions_fuzzy_ep(req: FuzzyScreenRequest):
    """Fuzzy entity sanctions screening with name-variant generation.

    Catches transliteration, acronym, and obfuscation attempts that exact-match
    screens miss. Backed by the OpenSanctions consolidated dataset.
    """
    if not req.name or len(req.name.strip()) < 2:
        raise HTTPException(status_code=400, detail="name required (min 2 chars)")
    if req.aliases:
        return await aria_sanctions.screen_with_aliases(req.name, req.aliases)
    return await aria_sanctions.fuzzy_screen(req.name, threshold=req.threshold)


