@router.get("/adversarial/amendments")
@fail_wire(module="aria", gap_type="engine_failure")
async def adversarial_amendments_ep():
    """Pending clause-amendment candidates staged from failed attacks.
    Human approves via self_improve.deploy_improvement per doctrine.

    R-F422 (2026-05-13): on-read maintenance.
    (a) Backfill missing fail_count / last_failed_at on legacy entries
        (the operator's 22:30 dashboard had 17 pre-R-F422 entries).
    (b) Auto-reject entries where last_failed_at > 14 days ago AND
        fail_count < 3 — those are stale low-priority duplicates the
        operator hasn't triaged. Audit-log the auto-reject to
        aria:adversarial:rejected_amendments with reason "R-F422
        auto-reject: stale, low fail_count" so the chain of custody
        survives. Entries with fail_count >= 3 STAY — high-failure
        attacks need real operator attention.
    """
    from ..intel import redis_store as rs
    from datetime import datetime, timezone, timedelta
    key_queue = "aria:adversarial:amendments_queue"
    queue = await rs.get_json(key_queue) or []

    now = datetime.now(timezone.utc)
    cutoff_iso = (now - timedelta(days=14)).isoformat()
    auto_rejected: list[dict] = []
    cleaned: list[dict] = []
    for entry in queue:
        if not isinstance(entry, dict):
            continue
        # Backfill last_failed_at + fail_count on pre-R-F422 legacy entries.
        if "last_failed_at" not in entry:
            entry["last_failed_at"] = entry.get("staged_at", now.isoformat())
        if "fail_count" not in entry:
            entry["fail_count"] = 1
        # Auto-reject stale low-priority duplicates.
        try:
            last_fail = entry.get("last_failed_at") or entry.get("staged_at") or ""
            fc = int(entry.get("fail_count", 1))
            if last_fail < cutoff_iso and fc < 3:
                auto_rejected.append({
                    **entry,
                    "rejected_at": now.isoformat(),
                    "rejected_by": "auto",
                    "rejected_reason": (
                        f"R-F422 auto-reject: stale (last_failed_at={last_fail[:10]} "
                        f">14d ago) and fail_count={fc}<3. No operator triage in "
                        f"window; high-failure attacks (fail_count>=3) STAY in queue."
                    ),
                })
                continue
        except Exception:
            pass
        cleaned.append(entry)

    # Persist the cleaned queue + audit-log the auto-rejections.
    if len(cleaned) != len(queue):
        try:
            await rs.set_json(key_queue, cleaned, ex=90 * 86400)
        except Exception:
            pass
        if auto_rejected:
            try:
                rej_key = "aria:adversarial:rejected_amendments"
                rejected_log = await rs.get_json(rej_key) or []
                rejected_log = auto_rejected + rejected_log
                await rs.set_json(rej_key, rejected_log[:500], ex=180 * 86400)
            except Exception:
                pass

    return {
        "queue_depth": len(cleaned),
        "amendments": cleaned,
        "_rf422_auto_rejected_this_call": len(auto_rejected),
    }


@router.post("/adversarial/amendments/reject")
@fail_wire(module="aria", gap_type="engine_failure")
async def adversarial_amendments_reject_ep(req: Request):
    """Reject a single staged amendment by attack_id with an explicit
    reason. Moves it from aria:adversarial:amendments_queue to
    aria:adversarial:rejected_amendments so the audit trail survives.
    Use this during operator triage instead of the blunt clear-all.

    Body: {"attack_id": "<id>", "reason": "<operator note>"}
    """
    try:
        body = await req.json()
    except Exception:
        raise HTTPException(status_code=400, detail="body must be JSON")
    if not isinstance(body, dict):
        raise HTTPException(status_code=400, detail="body must be a JSON object")
    attack_id = (body.get("attack_id") or "").strip()
    reason = (body.get("reason") or "").strip()
    if not attack_id:
        raise HTTPException(status_code=400, detail="attack_id required")
    if not reason:
        raise HTTPException(status_code=400, detail="reason required — operator must note why the amendment is rejected")
    from ..intel import redis_store as rs
    from datetime import datetime as _dt, timezone as _tz
    key_queue = "aria:adversarial:amendments_queue"
    key_rejected = "aria:adversarial:rejected_amendments"
    queue = await rs.get_json(key_queue) or []
    note = next((n for n in queue if isinstance(n, dict) and n.get("attack_id") == attack_id), None)
    if note is None:
        raise HTTPException(status_code=404, detail=f"no pending amendment for attack_id={attack_id}")
    rejection = dict(note)
    rejection["rejected_at"] = _dt.now(_tz.utc).isoformat()
    rejection["rejection_reason"] = reason[:500]
    rejected = await rs.get_json(key_rejected) or []
    rejected.insert(0, rejection)
    await rs.set_json(key_rejected, rejected[:500], ex=365 * 86400)
    await rs.set_json(
        key_queue,
        [n for n in queue if not (isinstance(n, dict) and n.get("attack_id") == attack_id)],
        ex=90 * 86400,
    )
    return {
        "ok": True,
        "attack_id": attack_id,
        "queue_depth_now": len(queue) - 1,
        "rejected_count": len(rejected) + 1,
    }


@router.post("/adversarial/amendments/reject-bulk")
@fail_wire(module="aria", gap_type="engine_failure")
async def adversarial_amendments_reject_bulk_ep(req: Request):
    """Bulk-reject every pending amendment matching any of the provided
    attack_ids, all with the same rejection reason. Used for operator
    triage sweeps (e.g. 'all amendments from attacks that now pass in
    the latest run are historical flake' — one reason, many rejections).

    Body: {"attack_ids": ["A1_X", "B1_Y", ...], "reason": "..."}
    """
    try:
        body = await req.json()
    except Exception:
        raise HTTPException(status_code=400, detail="body must be JSON")
    if not isinstance(body, dict):
        raise HTTPException(status_code=400, detail="body must be a JSON object")
    raw_ids = body.get("attack_ids") or []
    reason = (body.get("reason") or "").strip()
    if not isinstance(raw_ids, list) or not raw_ids:
        raise HTTPException(status_code=400, detail="attack_ids must be a non-empty list")
    if not reason:
        raise HTTPException(status_code=400, detail="reason required")
    target_ids = {str(a).strip() for a in raw_ids if str(a).strip()}
    from ..intel import redis_store as rs
    from datetime import datetime as _dt, timezone as _tz
    now_iso = _dt.now(_tz.utc).isoformat()
    key_queue = "aria:adversarial:amendments_queue"
    key_rejected = "aria:adversarial:rejected_amendments"
    queue = await rs.get_json(key_queue) or []
    rejected = await rs.get_json(key_rejected) or []
    moved = []
    kept = []
    for note in queue:
        if isinstance(note, dict) and note.get("attack_id") in target_ids:
            rej = dict(note)
            rej["rejected_at"] = now_iso
            rej["rejection_reason"] = reason[:500]
            moved.append(rej)
        else:
            kept.append(note)
    rejected = moved + rejected
    await rs.set_json(key_rejected, rejected[:500], ex=365 * 86400)
    await rs.set_json(key_queue, kept, ex=90 * 86400)
    return {
        "ok": True,
        "removed": len(moved),
        "remaining": len(kept),
        "matched_ids": sorted({m["attack_id"] for m in moved}),
    }


