def _amendment_key(a: dict) -> tuple:
    """R-F2030 — identity of an amendment: (attack_id, sorted anchor clauses)."""
    return (
        (a.get("attack_id") or ""),
        tuple(sorted(a.get("anchor_clauses") or [])),
    )


def _collapse_approved_amendments(approved: list) -> list:
    """R-F2030 — collapse duplicate approved amendments by (attack_id,
    anchor_clauses). The approve flow was append-only with no dedup, so a
    recurring attack stacked identical records (live 2026-06-27: 49 entries,
    only 13 unique — C1 ×12). Keep the MOST RECENT record per key, carry a
    reapproval_count, max the fail_count, and preserve first_approved_at.
    Order-preserving (newest-first, matching the insert(0, …) convention).
    """
    by_key: dict = {}
    order: list = []
    for a in approved:
        if not isinstance(a, dict):
            continue
        key = _amendment_key(a)
        if key in by_key:
            kept = by_key[key]
            a_ts = a.get("approved_at") or ""
            k_ts = kept.get("approved_at") or ""
            newer = a if a_ts >= k_ts else kept
            merged = dict(newer)
            merged["reapproval_count"] = (
                kept.get("reapproval_count", 1) + a.get("reapproval_count", 1)
            )
            merged["fail_count"] = max(
                a.get("fail_count", 0) or 0, kept.get("fail_count", 0) or 0
            )
            _firsts = [t for t in (
                a.get("first_approved_at"), kept.get("first_approved_at"), a_ts, k_ts,
            ) if t]
            if _firsts:
                merged["first_approved_at"] = min(_firsts)
            by_key[key] = merged
        else:
            rec = dict(a)
            rec.setdefault("reapproval_count", 1)
            rec.setdefault("first_approved_at", rec.get("approved_at"))
            by_key[key] = rec
            order.append(key)
    return [by_key[k] for k in order]


async def _resolve_amendment_deploy_status(staged_improvement_id) -> str:
    """R-F2031 — the honest live deploy state of an approved amendment's staged
    improvement, so we never tell the operator to POST a dead id. Returns one of:
      staged   — still in the staged queue, deployable now
      deployed — applied to live ARIA (improvement_log records the deploy)
      gone     — was staged but no longer present (collapsed/expired/applied) —
                 re-approve to mint a fresh deployable staged item
      none     — no staged id was ever recorded
    """
    if not staged_improvement_id:
        return "none"
    try:
        from ..intel import redis_store as rs
        from ..intel.self_improve import STAGED_KEY, IMPROVEMENT_LOG_KEY
        staged = await rs.get_json(STAGED_KEY) or []
        for s in staged:
            if isinstance(s, dict) and s.get("id") == staged_improvement_id:
                return s.get("status") or "staged"
        log = await rs.get_json(IMPROVEMENT_LOG_KEY) or []
        for e in log:
            if (isinstance(e, dict) and e.get("id") == staged_improvement_id
                    and e.get("action") == "deployed"):
                return "deployed"
    except Exception:
        return "unknown"
    return "gone"


@router.post("/adversarial/amendments/approve")
@fail_wire(module="aria", gap_type="engine_failure")
async def adversarial_amendments_approve_ep(req: Request):
    """R-F168 (2026-05-11): bridge an amendment into staged_improvements
    so it can be applied via self_improve.deploy_improvement.

    Pre-R-F168: amendments_queue and staged_improvements were two
    disconnected keyspaces. Operators could only reject; 17 amendments
    sat for ~3 weeks with no apply path. This endpoint reads the queued
    amendment, builds a new constitution version by appending the
    amendment as a fresh clause at the end of ARIA_SYSTEM_PROMPT, and
    stages it for deploy. The actual deploy still requires the manual
    POST /api/aria/self/deploy/{staged_id} step (operator safety gate).

    Body: {"attack_id": "<id>", "notes": "<operator approval note>"}
    """
    try:
        body = await req.json()
    except Exception:
        raise HTTPException(status_code=400, detail="body must be JSON")
    if not isinstance(body, dict):
        raise HTTPException(status_code=400, detail="body must be a JSON object")
    attack_id = (body.get("attack_id") or "").strip()
    notes = (body.get("notes") or "").strip()
    if not attack_id:
        raise HTTPException(status_code=400, detail="attack_id required")

    from ..intel import redis_store as rs
    from ..intel import self_improve as _si
    from datetime import datetime as _dt, timezone as _tz

    key_queue = "aria:adversarial:amendments_queue"
    key_approved = "aria:adversarial:approved_amendments"

    queue = await rs.get_json(key_queue) or []
    # R-F215 (2026-05-11) — guard against non-dict entries. A legacy /
    # corrupted snapshot could carry a string or other type; without
    # the isinstance check, `n.get` would raise AttributeError and
    # 500 the whole endpoint.
    matched = [
        n for n in queue
        if isinstance(n, dict) and (n.get("attack_id") or "") == attack_id
    ]
    if not matched:
        raise HTTPException(
            status_code=404,
            detail=f"no pending amendment with attack_id={attack_id}",
        )
    amendment = matched[0]

    # R-F2030 — IDEMPOTENT approve. Pre-R-F2030 every call re-appended a clause,
    # re-staged, and inserted another approved record — so a recurring attack
    # stacked identical clauses + minted fresh-then-stale staged ids (the source
    # of the misleading "POST /self/deploy/<dead-id>"). If this (attack_id,
    # anchor_clauses) is already approved AND its staged item is still deployable
    # or already deployed, short-circuit: bump the count, clear it off the queue,
    # and return the EXISTING staged id + its honest status. Only re-stage when
    # the prior staged item is GONE (so the operator gets a fresh deployable one).
    _approved_now = await rs.get_json(key_approved) or []
    _akey = _amendment_key(amendment)
    _dup = next(
        (a for a in _approved_now
         if isinstance(a, dict) and _amendment_key(a) == _akey),
        None,
    )
    if _dup is not None:
        _sid = _dup.get("staged_improvement_id")
        _status = await _resolve_amendment_deploy_status(_sid)
        if _status in ("staged", "pending", "deployed"):
            _dup["reapproval_count"] = _dup.get("reapproval_count", 1) + 1
            _dup["last_approved_at"] = _dt.now(_tz.utc).isoformat()
            if notes:
                _dup["operator_notes"] = notes
            _kept = [
                n for n in queue
                if not isinstance(n, dict) or (n.get("attack_id") or "") != attack_id
            ]
            await rs.set_json(
                key_approved, _collapse_approved_amendments(_approved_now)[:500],
                ex=365 * 86400,
            )
            await rs.set_json(key_queue, _kept, ex=90 * 86400)
            return {
                "ok": True,
                "attack_id": attack_id,
                "idempotent": True,
                "staged_improvement_id": _sid,
                "deploy_status": _status,
                "reapproval_count": _dup["reapproval_count"],
                "next_step": (
                    f"already {_status}"
                    + (f" — POST /api/aria/self/deploy/{_sid} to apply"
                       if _status in ("staged", "pending") else " (no action needed)")
                ),
                "queue_remaining": len(_kept),
            }
        # status == gone/none/unknown → fall through and re-stage a fresh item.

    # Read current aria_engine.py and append the amendment as a new
    # clause at the bottom of ARIA_SYSTEM_PROMPT.
    code_read = await _si.read_own_code("aria_service/aria_engine.py")
    if "error" in code_read:
        raise HTTPException(status_code=500, detail=f"read failed: {code_read['error']}")
    src = code_read["content"]

    # Locate the prompt block. The constant is defined as:
    #   ARIA_SYSTEM_PROMPT = """ ... """
    # Find the closing triple-quote of that constant and inject a new
    # clause line just before it.
    import re as _re
    m = _re.search(
        r'(ARIA_SYSTEM_PROMPT\s*=\s*"""[\s\S]+?)("""\s*\n)',
        src,
    )
    if not m:
        raise HTTPException(
            status_code=500,
            detail="could not locate ARIA_SYSTEM_PROMPT block in aria_engine.py",
        )
    block_body, block_close = m.group(1), m.group(2)

    # Highest existing numbered clause — append the new one at N+1.
    nums = [int(x) for x in _re.findall(r"(?:^|\n)(\d+)\.\s", block_body)]
    next_n = max(nums) + 1 if nums else 24
    amend_text = (amendment.get("proposed_amendment") or "").strip()
    if not amend_text:
        amend_text = "(no proposed text supplied — operator notes only)"
    # R-F2030 — append-guard. Never add a duplicate clause if this attack's
    # amendment text is already present in the prompt (defense-in-depth beneath
    # the idempotency check above, e.g. if the approved store was cleared but the
    # clause remains). Signature = attack_id + the head of the amendment text.
    _clause_sig = f"adversarial attack {attack_id}. {amend_text[:80]}"
    if _clause_sig in src:
        raise HTTPException(
            status_code=409,
            detail=(f"clause for {attack_id} already present in ARIA_SYSTEM_PROMPT — "
                    f"not appending a duplicate (R-F2030)"),
        )
    new_clause_line = (
        f"\n{next_n}. R-F168 — staged from adversarial attack {attack_id}. "
        f"{amend_text[:600]}\n"
        f"   (Operator approved: {notes[:200] or 'no notes'} · "
        f"approved_at {_dt.now(_tz.utc).isoformat()})\n"
    )
    new_src = src.replace(
        block_body + block_close,
        block_body + new_clause_line + block_close,
        1,
    )

    staged_res = await _si.stage_improvement(
        file_path="aria_service/aria_engine.py",
        new_content=new_src,
        change_type="prompt_evolution",
        description=(
            f"R-F168 — approve adversarial amendment {attack_id} "
            f"(anchor clauses: {amendment.get('anchor_clauses')})"
        ),
        reasoning=f"Operator approval note: {notes or '(none)'}",
    )
    if "error" in staged_res:
        raise HTTPException(status_code=500, detail=f"stage_improvement failed: {staged_res['error']}")

    # Move the amendment off the queue into the approved bin.
    # R-F215 (2026-05-11) — same isinstance guard as above; keep non-
    # dict legacy entries intact rather than crashing the endpoint.
    kept = [
        n for n in queue
        if not isinstance(n, dict) or (n.get("attack_id") or "") != attack_id
    ]
    approved = await rs.get_json(key_approved) or []
    record = dict(amendment)
    record["approved_at"] = _dt.now(_tz.utc).isoformat()
    record["first_approved_at"] = record.get("approved_at")
    record["operator_notes"] = notes
    record["staged_improvement_id"] = staged_res.get("id")
    record["reapproval_count"] = 1
    approved.insert(0, record)
    # R-F2030 — collapse duplicates on write so the store can never run away.
    approved = _collapse_approved_amendments(approved)
    await rs.set_json(key_approved, approved[:500], ex=365 * 86400)
    await rs.set_json(key_queue, kept, ex=90 * 86400)

    return {
        "ok": True,
        "attack_id": attack_id,
        "staged_improvement_id": staged_res.get("id"),
        "deploy_status": "staged",  # R-F2031 — freshly staged, deployable now
        "next_step": (
            f"POST /api/aria/self/deploy/{staged_res.get('id')} to apply "
            f"the constitution amendment to live ARIA"
        ),
        "queue_remaining": len(kept),
        "approved_total": len(approved),
    }


@router.get("/adversarial/amendments/approved")
@fail_wire(module="aria", gap_type="engine_failure")
async def adversarial_amendments_approved_ep(limit: int = 100):
    """R-F168: audit surface — amendments the operator has approved.
    Each entry carries staged_improvement_id so the operator can chase
    the deploy state via /self/deploy/{id}.

    R-F2030/R-F2031 — dedup-on-read-and-persist (self-heals the legacy runaway
    pile: 49 → 13 unique) AND resolve each entry's LIVE deploy_status so the
    operator is never pointed at a dead /self/deploy/<stale-id> command.
    """
    from ..intel import redis_store as rs
    key = "aria:adversarial:approved_amendments"
    raw = await rs.get_json(key) or []
    collapsed = _collapse_approved_amendments(raw)
    # Persist the collapse once (idempotent) so the stored pile actually shrinks.
    if len(collapsed) != len(raw):
        try:
            await rs.set_json(key, collapsed[:500], ex=365 * 86400)
        except Exception:
            pass
    out = []
    for a in collapsed[: max(1, min(limit, 500))]:
        rec = dict(a)
        rec["deploy_status"] = await _resolve_amendment_deploy_status(
            a.get("staged_improvement_id")
        )
        out.append(rec)
    return {
        "count": len(collapsed),
        "raw_count_before_dedup": len(raw),
        "approved": out,
    }


@router.post("/adversarial/amendments/clear")
@fail_wire(module="aria", gap_type="engine_failure")
async def adversarial_amendments_clear_ep(staged_within_seconds: int | None = None):
    """Drop pending amendments. Used to purge false amendments staged from
    LLM-degraded runs (the run_weekly invalid-run guard prevents new ones,
    but existing entries from before the guard need a one-shot clear).

    Pass `staged_within_seconds=N` to drop only amendments newer than N
    seconds ago (e.g. 86400 for last 24h). Omit to clear the entire queue.
    Returns counts."""
    from datetime import datetime as _dt, timezone as _tz
    from ..intel import redis_store as rs
    key = "aria:adversarial:amendments_queue"
    queue = await rs.get_json(key) or []
    before = len(queue)
    if staged_within_seconds is None:
        kept: list = []
    else:
        cutoff = _dt.now(_tz.utc).timestamp() - staged_within_seconds
        kept = []
        for note in queue:
            try:
                staged = _dt.fromisoformat(note.get("staged_at", "").replace("Z", "+00:00"))
                if staged.timestamp() < cutoff:
                    kept.append(note)
            except Exception:
                kept.append(note)
    await rs.set_json(key, kept, ex=90 * 86400)
    return {"removed": before - len(kept), "remaining": len(kept), "before": before}


@router.get("/metrics/grounded_rate")
@fail_wire(module="aria", gap_type="engine_failure")
async def metrics_grounded_rate_ep(days: int = 14):
    """Return the grounded-rate baseline + a time-series over the last
    N days (default 14). Source: source_verifier.record_verification
    has been logging every chat verification since 2026-04-09. The
    dashboard reads the stats and renders a simple trend."""
    from ..intel import source_verifier
    overall = await source_verifier.get_verification_stats()
    # Recent verifications (up to 500, most-recent first)
    try:
        recents = await source_verifier.list_verifications(limit=500)
    except Exception:
        recents = []
    # Bucket by day for the time-series
    from collections import defaultdict
    from datetime import datetime as _dt, timezone as _tz, timedelta as _td
    now = _dt.now(_tz.utc)
    buckets: dict[str, dict] = defaultdict(
        lambda: {"count": 0, "grounded_sum": 0.0, "paraphrase_violations": 0}
    )
    paraphrase_flag_count = 0
    for v in recents:
        ts = v.get("recorded_at") or v.get("created_at") or v.get("ts") or ""
        try:
            d = _dt.fromisoformat(ts.replace("Z", "+00:00"))
        except Exception:
            continue
        if (now - d).days > days:
            continue
        key = d.date().isoformat()
        b = buckets[key]
        b["count"] += 1
        gr = v.get("grounded_rate")
        if gr is not None:
            b["grounded_sum"] += float(gr)
        if v.get("paraphrase_violation"):
            b["paraphrase_violations"] += 1
            paraphrase_flag_count += 1
    series = []
    for i in range(days - 1, -1, -1):
        date_key = (now - _td(days=i)).date().isoformat()
        b = buckets.get(date_key, {"count": 0, "grounded_sum": 0.0, "paraphrase_violations": 0})
        avg = (b["grounded_sum"] / b["count"]) if b["count"] else None
        series.append({
            "date": date_key,
            "verifications": b["count"],
            "avg_grounded_rate": round(avg, 3) if avg is not None else None,
            "paraphrase_violations": b["paraphrase_violations"],
        })
    # Baseline = mean grounded_rate across the window, excluding None
    rates = [s["avg_grounded_rate"] for s in series if s["avg_grounded_rate"] is not None]
    baseline = round(sum(rates) / len(rates), 3) if rates else None
    return {
        "window_days": days,
        "overall_stats": overall,
        "baseline_grounded_rate": baseline,
        "paraphrase_violations_in_window": paraphrase_flag_count,
        "series": series,
    }


