def _normalise_vault_source_url(url: str) -> str:
    """Return a stable comparison key for vault/source-monitor URLs."""
    from urllib.parse import parse_qsl, urlencode, urlparse

    raw = (url or "").strip()
    if not raw:
        return ""
    parsed = urlparse(raw)
    host = (parsed.hostname or "").lower()
    port = parsed.port
    if port and port not in {80, 443}:
        host = f"{host}:{port}"
    path = (parsed.path or "/").rstrip("/") or "/"
    query = urlencode(sorted(
        (key, value) for key, value in parse_qsl(parsed.query, keep_blank_values=True)
        if not key.lower().startswith("utm_")
    ))
    return f"{host}{path}" + (f"?{query}" if query else "")


def _validate_manual_source_research(metadata: Any) -> str | None:
    """Return a precise admission error when a manual source lacks research."""
    from urllib.parse import urlparse

    if not isinstance(metadata, dict):
        return "research metadata is required"
    raw_topics = metadata.get("topics")
    raw_evidence = metadata.get("evidence_urls")
    if not isinstance(raw_topics, list):
        return "topics must be a list"
    if not isinstance(raw_evidence, list):
        return "evidence_urls must be a list"
    topics = [str(v).strip() for v in raw_topics if str(v).strip()]
    summary = str(metadata.get("research_summary") or "").strip()
    rationale = str(metadata.get("relevance_rationale") or "").strip()
    evidence = [
        str(v).strip() for v in raw_evidence
        if str(v).strip()
    ]
    if not topics:
        return "at least one relevance topic is required"
    if len(summary) < 80:
        return "research_summary must be at least 80 characters"
    if len(rationale) < 40:
        return "relevance_rationale must be at least 40 characters"
    evidence_hosts = {
        (urlparse(value).hostname or "").lower().removeprefix("www.")
        for value in evidence
    }
    evidence_hosts.discard("")
    if len(evidence_hosts) < 2:
        return "evidence URLs must cover at least two independent domains"
    from ..intel import security as _sec
    for evidence_url in evidence:
        ok, why = _sec.validate_url(evidence_url)
        if not ok:
            return f"unsafe evidence URL: {why}"
    return None


def _vault_ingestion_contract(site_type: str) -> dict[str, Any]:
    """Describe where a vault row will flow after it is saved."""
    feed_type = (site_type or "").lower() in {"rss", "website"}
    return {
        "ingestion_enabled": feed_type,
        "output": "news_monitor.vault_curated" if feed_type else "vault.catalogue",
        "message": (
            "Website/RSS source will be read by News Monitor and promoted into dashboard intel."
            if feed_type
            else "Portal/API source is catalogued for operator credentials and is not auto-ingested."
        ),
    }


def _find_vault_source_duplicate(vault: Any, *, site_id: str, site_url: str) -> dict[str, Any] | None:
    """Find an existing vault row by id or normalised URL."""
    existing_by_id = vault.get(site_id)
    if existing_by_id:
        return existing_by_id
    target = _normalise_vault_source_url(site_url)
    if not target:
        return None
    for entry in vault.list(limit=1000):
        if _normalise_vault_source_url(entry.get("site_url", "")) == target:
            return entry
    return None


def _find_source_monitor_duplicate(site_url: str) -> dict[str, Any] | None:
    """Return the built-in News Monitor source matching this URL, if any."""
    target = _normalise_vault_source_url(site_url)
    if not target:
        return None
    from ..intel import news_monitor

    for name, url, category, _lang, tier, topics in news_monitor.NEWS_SOURCES:
        if _normalise_vault_source_url(url) == target:
            return {
                "name": name,
                "url": url,
                "category": category,
                "tier": tier,
                "topics": topics,
            }
    return None


