# ── R-F2045 — per-USER data sources (their dashboard) ───────────────────────
# A signed-in user adds their own data-point sites. These reuse the SAME vault
# store + the SAME news_monitor ingestion (R-F2046) as admin sources — scoped by
# agent_id="user:<uid>" so a user only ever reads/writes their own. Shared by
# design (MVP): a user's public source enriches the global pool (benefits ARIA +
# all users), per the operator's model. user_id is pinned from the JWT by the web
# tier (requireAuth) and passed as a query param — never trusted from the client.
_USER_SOURCE_LIMIT = 25


@router.get("/user/sources")
@fail_wire(module="aria", gap_type="engine_failure")
async def user_sources_list_ep(user_id: str = "") -> dict:
    from ..intel.agent_signup_vault import get_vault
    if not user_id:
        return {"success": True, "sources": [], "count": 0}
    entries = get_vault().list(agent_id=f"user:{user_id}", limit=200)
    return {"success": True, "sources": entries, "count": len(entries)}


@router.post("/user/sources")
@fail_wire(module="aria", gap_type="engine_failure")
async def user_sources_add_ep(request: Request, user_id: str = "") -> dict:
    from ..intel.agent_signup_vault import get_vault
    from ..intel import security as _sec
    import hashlib
    if not user_id:
        return {"success": False, "error": "authentication required"}
    body = await request.json()
    name = (body.get("name") or "").strip()
    url = (body.get("url") or "").strip()
    site_type = (body.get("site_type") or "rss").lower()
    notes = (body.get("notes") or "").strip()
    if not name or not url:
        return {"success": False, "error": "name and url are required"}
    if site_type not in ("rss", "website"):
        return {"success": False, "error": "site_type must be 'rss' or 'website'"}
    ok, why = _sec.validate_url(url)
    if not ok:
        return {"success": False, "error": f"unsafe URL: {why}"}
    owner = f"user:{user_id}"
    vault = get_vault()
    existing = vault.list(agent_id=owner, limit=500)
    if len(existing) >= _USER_SOURCE_LIMIT:
        return {"success": False, "error": f"source limit reached ({_USER_SOURCE_LIMIT}) — remove one first"}
    for e in existing:
        if (e.get("site_url") or "").strip() == url:
            return {"success": False, "error": "you have already added this source"}
    # R-F2245 — domain-diversity guard (operator directive: the vault must NOT
    # accumulate the same web-data domains → source collusion / repetitive data).
    # Cap sources per registrable domain so one site can't dominate a user's vault.
    import os as _os_v
    import urllib.parse as _up_v
    def _srcdom(u: str) -> str:
        try:
            return (_up_v.urlparse(u).hostname or "").replace("www.", "").lower()
        except Exception:
            return ""
    _new_dom = _srcdom(url)
    if _new_dom:
        try:
            _cap = int(_os_v.getenv("ARIA_VAULT_MAX_PER_DOMAIN", "2") or "2")
        except Exception:
            _cap = 2
        _same = sum(1 for e in existing if _srcdom((e.get("site_url") or "").strip()) == _new_dom)
        if _cap > 0 and _same >= _cap:
            return {"success": False, "error": f"you already have {_same} source(s) from '{_new_dom}' — add a DIFFERENT domain to keep your intelligence diverse; multiple feeds from one site create repetitive, echo-chamber data."}
    sid = "u_" + hashlib.sha1(f"{user_id}|{url}".encode(), usedforsecurity=False).hexdigest()[:16]
    # R-F2213 — probe the URL so the stored status is TRUTHFUL (§22). Pre-fix this
    # hardcoded status="verified" with NO fetch, so a typo/dead URL entered the poll
    # set already labelled "verified". The probe is SSRF-safe because validate_url
    # (R-F2212) already resolved + blocked internal/private hosts; follow_redirects
    # =False keeps it safe against a public→internal redirect. Reachable 2xx+body →
    # "verified"; anything else (3xx/4xx/5xx/timeout) → "pending" (still ingested —
    # news_monitor retries it) with a note. A probe failure NEVER blocks the add.
    status = "verified"
    note_extra = ""
    try:
        import httpx as _httpx
        async with _httpx.AsyncClient(timeout=10.0, follow_redirects=False) as _pc:
            _pr = await _pc.get(url, headers={"User-Agent": "Crucix/1.0 (+source-verify)"})
        if 200 <= _pr.status_code < 300 and (_pr.text or "").strip():
            status = "verified"
        else:
            status, note_extra = "pending", f" [probe: HTTP {_pr.status_code}]"
    except Exception as _pe:
        status, note_extra = "pending", f" [probe: unreachable — {str(_pe)[:60]}]"
    try:
        entry = vault.record(
            site_id=sid, site_name=name, site_url=url, agent_id=owner,
            site_type=site_type, agent_type="user_source", status=status,
            notes=(notes + note_extra).strip(),
        )
    except Exception as _re:
        _log.warning("[user_sources] record failed for %s: %s", url[:80], _re)
        return {"success": False, "error": "source could not be saved (storage error)"}
    # Verify the write actually landed before reporting success (no false-success).
    if not entry or vault.get(sid) is None:
        return {"success": False, "error": "source could not be saved"}
    return {"success": True, "entry": entry, "verified": status == "verified"}


