@router.post("/learning/sync", dependencies=[Depends(require_aria_token)])  # R-F1347: was unauth brain WRITE
@fail_wire(module="aria", gap_type="engine_failure")
async def learning_sync_ep(request: Request) -> dict:
    """Receive learning data from ARIA clients.

    Client interactions (queries + responses) are fed into ARIA's
    brain_hook pipeline so the neural memory and gap detector learn
    from every user interaction across all clients.
    """
    body = await request.json()
    interactions = body.get("interactions", [])
    client_id = body.get("client_id", "unknown")
    client_version = body.get("client_version", "unknown")

    if not interactions:
        return {"status": "ok", "received": 0, "message": "no interactions to sync"}

    absorbed = 0
    for interaction in interactions:
        try:
            from ..intel import brain_hook as _bh
            await _bh.absorb(
                module="client_learning",
                content=json.dumps({
                    "query": interaction.get("query", "")[:2000],
                    "response": interaction.get("response", "")[:5000],
                    "model_used": interaction.get("model_used", "unknown"),
                    "tokens_used": interaction.get("tokens_used", 0),
                    "cost": interaction.get("cost", 0),
                    "user_feedback": interaction.get("user_feedback"),
                    "client_id": client_id,
                    "client_version": client_version,
                    "platform": interaction.get("platform", ""),
                }),
                source="client_sync",
                tags=["client_learning", f"client_{client_id[:8]}"],
            )
            absorbed += 1
        except Exception as e:
            _log.debug("[learning_sync] absorb failed for interaction: %s", e)

    _log.info(
        "[learning_sync] client=%s v=%s: absorbed %d/%d interactions",
        client_id[:12], client_version, absorbed, len(interactions),
    )

    return {
        "status": "ok",
        "received": len(interactions),
        "absorbed": absorbed,
        "client_id": client_id,
    }


@router.get("/learning/updates", dependencies=[Depends(require_aria_token)])  # R-F1347: was unauth gap/mistake leak
@fail_wire(module="aria", gap_type="engine_failure")
async def learning_updates_ep(
    client_id: str = "",
    client_version: str = "",
) -> dict:
    """Send updated learning patterns to ARIA clients.

    Returns recent capability gaps and mistake patterns that the
    client can use to improve local suggestions.
    """
    patterns = []

    try:
        from ..intel import capability_gaps as _cg
        gaps = await _cg.recent(limit=20)
        for gap in gaps:
            patterns.append({
                "type": "capability_gap",
                "data": {
                    "title": getattr(gap, "title", str(gap)),
                    "description": getattr(gap, "description", ""),
                    "severity": getattr(gap, "severity", "medium"),
                },
                "confidence": 0.8,
            })
    except Exception as e:
        _log.debug("[learning_updates] capability_gaps failed: %s", e)

    try:
        from ..intel import mistake_ledger as _ml
        mistakes = await _ml.recent(limit=20)
        for mistake in mistakes:
            patterns.append({
                "type": "mistake_pattern",
                "data": {
                    "what": getattr(mistake, "what", str(mistake)),
                    "category": getattr(mistake, "category", "unknown"),
                    "severity": getattr(mistake, "severity", "medium"),
                },
                "confidence": 0.7,
            })
    except Exception as e:
        _log.debug("[learning_updates] mistake_ledger failed: %s", e)

    _log.debug(
        "[learning_updates] client=%s v=%s: returning %d patterns",
        client_id[:12] if client_id else "?", client_version, len(patterns),
    )

    return {
        "patterns": patterns,
        "version": client_version,
        "client_id": client_id,
        "count": len(patterns),
    }


# ── RunPod pod management (R-F1642) ──────────────────────────────────────
# Lets a training/eval cycle (Claude or ARIA) drive the GPU pod and, crucially,
# CLAIM it so the on-box stop-only scheduler does not force-stop it mid-run.
# All token-gated. Stop-only mode means the pod never auto-starts; these give
# explicit, audited control + the work-claim that protects an active run.

@router.get("/runpod/status", dependencies=[Depends(require_aria_token)])
@fail_wire(module="aria", gap_type="engine_failure")
async def runpod_status_ep() -> dict:
    from ..intel import runpod_scheduler as _rps
    out = _rps.get_status()
    try:
        if _rps.configured():
            out["pod_status_live"] = await _rps.get_pod_status()
    except Exception as e:  # surfaced, never silently hidden (§22)
        out["pod_status_live"] = None
        out["probe_error"] = str(e)[:160]
    return out


@router.post("/runpod/claim", dependencies=[Depends(require_aria_token)])
@fail_wire(module="aria", gap_type="engine_failure")
async def runpod_claim_ep(ttl_s: float = 7200.0, reason: str = "") -> dict:
    """Hold the pod for ttl_s seconds — protects it from the stop-only sweep."""
    from ..intel import runpod_scheduler as _rps
    return {"ok": True, "claim": _rps.claim_pod(ttl_s=ttl_s, reason=reason)}


@router.post("/runpod/release", dependencies=[Depends(require_aria_token)])
@fail_wire(module="aria", gap_type="engine_failure")
async def runpod_release_ep() -> dict:
    from ..intel import runpod_scheduler as _rps
    return {"ok": True, "released": _rps.release_pod()}


@router.post("/runpod/start", dependencies=[Depends(require_aria_token)])
@fail_wire(module="aria", gap_type="engine_failure")
async def runpod_start_ep(ttl_s: float = 7200.0, reason: str = "manual start") -> dict:
    """Claim THEN start — so the scheduler protects the pod we just started."""
    from ..intel import runpod_scheduler as _rps
    if not _rps.configured():
        return {"ok": False, "error": "runpod not configured (key/pod_id)"}
    claim = _rps.claim_pod(ttl_s=ttl_s, reason=reason)
    try:
        res = await _rps.start_pod()
        return {"ok": True, "claim": claim, "start": res}
    except Exception as e:
        return {"ok": False, "claim": claim, "error": str(e)[:200]}


@router.post("/runpod/stop", dependencies=[Depends(require_aria_token)])
@fail_wire(module="aria", gap_type="engine_failure")
async def runpod_stop_ep() -> dict:
    """Stop THEN release the claim (cycle finished)."""
    from ..intel import runpod_scheduler as _rps
    if not _rps.configured():
        return {"ok": False, "error": "runpod not configured (key/pod_id)"}
    try:
        res = await _rps.stop_pod()
        _rps.release_pod()
        return {"ok": True, "stop": res}
    except Exception as e:
        return {"ok": False, "error": str(e)[:200]}


# ── R-F3730 — Cure Protocol Phase 0.3 observation surface ────────────────────
# The census can classify a module statically and by test coverage, but the
# third proof (Phase 4.1) is runtime observation. This is where that evidence is
# read back so the overlay can be built. Bearer-gated by the router.
@router.get("/cure/usage")
# R-F3767 — §21a. The Phase 0.3 usage read-out. Its sibling write path was wired
# in R-F3737 for the same reason: this is the RUNTIME PROOF deciding whether 109
# dead-candidate modules may be deleted, so a failed read that renders as "no
# usage" is the reading that makes a LIVE module look deletable.
@fail_wire(module="aria", gap_type="engine_failure")
async def cure_usage_ep() -> dict:
    """Runtime route-usage observed since instrumentation went live.

    `available: false` means the store could not be READ — it does NOT mean
    nothing was observed. Collapsing those two is the CLAUDE.md §1 gate-#4
    failure class, where an absent key read as a clean pass for months.
    """
    from ..intel import cure_usage as _cu
    snap = await _cu.snapshot()
    if not snap.get("available"):
        return {
            "ok": False,
            "phase": "0.3",
            "deletion_authorised": False,
            "reason": snap.get("reason", "unknown"),
            "note": "could not measure — NOT the same as 'nothing observed'",
        }
    return {
        "ok": True,
        "phase": "0.3",
        # Deletion stays forbidden until an operator closes the window; this
        # endpoint reports evidence, it does not grant authority.
        "deletion_authorised": False,
        "observed_routes": snap["observed_routes"],
        "total_requests": snap["total_requests"],
        "pending_in_buffer": snap["pending_in_buffer"],
        "meta": snap.get("meta", {}),
        "routes": snap["routes"],
    }
